    // =========================================================================
    // COURSE 1 — Microsoft Excel Mastery
    // =========================================================================
    private function excelCourse(int $trainerId): void
    {
        $course = Course::updateOrCreate(
            ['title' => 'Microsoft Excel Mastery: Beginner to Advanced'],
            [
                'description'    => 'Jifunza Excel kutoka mwanzo kabisa hadi kiwango cha juu cha kitaalamu. Utajifunza formulas, functions, PivotTables, charts, na data analysis — zana ambazo zinahitajika katika kazi yoyote ya biashara au fedha.',
                'category'       => 'excel',
                'level'          => 'beginner',
                'duration_hours' => 18,
                'price_tzs'      => 0,
                'instructor_id'  => $trainerId,
                'created_by'     => $trainerId,
                'status'         => 'published',
                'published_at'   => now(),
                'approved_at'    => now(),
            ]
        );

        // MODULE 1
        $m1 = $this->mod($course, 1, 'Misingi ya Excel (Excel Fundamentals)', 'Jifunza interface, navigation, na data entry. Hii ni msingi wa kila kitu kingine.');

        $l = $this->lesson($m1, 1, 'Excel Interface na Navigation', 'Jifunza ribbon, cells, rows, columns, na jinsi ya kusogea kwenye spreadsheet kwa ufanisi.', 720,
            [['video_youtube', 'Interface ya Excel - Mwongozo Kamili', 'https://www.youtube.com/watch?v=rwbho0CgEAI']],
            '<h2>Excel Interface na Navigation</h2><p>Microsoft Excel imegawanywa katika sehemu kuu tatu: <strong>Ribbon</strong> (toolbar juu), <strong>Worksheet</strong> (gridi ya cells), na <strong>Formula Bar</strong> (inaonyesha maudhui ya cell iliyochaguliwa).</p><h3>Sehemu Muhimu za Interface</h3><ul><li><strong>Ribbon:</strong> Ina tabs — Home, Insert, Page Layout, Formulas, Data, Review, View</li><li><strong>Name Box:</strong> Inaonyesha anwani ya cell (mfano: A1, B5)</li><li><strong>Formula Bar:</strong> Inaonyesha formula au thamani ya cell</li><li><strong>Sheet Tabs:</strong> Chini ya worksheet — unaweza kuwa na sheets nyingi katika workbook moja</li></ul><h3>Njia za Haraka (Keyboard Shortcuts)</h3><ol><li><code>Ctrl + Home</code> — Rudi cell A1</li><li><code>Ctrl + End</code> — Nenda cell ya mwisho yenye data</li><li><code>Ctrl + Arrow Keys</code> — Ruka hadi mwisho wa data</li><li><code>F5</code> — Go To (nenda cell yoyote moja kwa moja)</li></ol><blockquote><strong>Tip:</strong> Tumia <code>Ctrl + Z</code> kufuta hatua na <code>Ctrl + Y</code> kurudisha. Hizi ndizo shortcuts muhimu zaidi za kuokoa wakati wako.</blockquote>');
        $this->assignment($l, 'Kazi ya Kwanza: Explore Excel Interface', 'Fungua Excel na ufanye yafuatayo: (1) Andika jina lako katika cell A1, (2) Andika tarehe ya leo katika B1, (3) Badilisha font ya A1 kuwa Bold na rangi ya bluu, (4) Unda worksheet mpya na uiite "Mazoezi", (5) Chukua screenshot ya kazi yako. Wasilisha kama Excel file (.xlsx)', 30, 3);

        $l = $this->lesson($m1, 2, 'Kuingiza na Kuformat Data', 'Aina za data (text, numbers, dates), formatting (bold, colors, borders), na cell alignment.', 900,
            [['video_youtube', 'Data Entry na Formatting', 'https://www.youtube.com/watch?v=p_A2J6YoMOk']],
            '<h2>Kuingiza na Kuformat Data katika Excel</h2><p>Excel inakubali aina tatu kuu za data: <strong>Text</strong> (maneno), <strong>Numbers</strong> (nambari), na <strong>Dates</strong> (tarehe). Kila aina ina tabia yake ya kawaida — text inapanga kushoto, nambari na tarehe zinapanga kulia.</p><h3>Formatting Muhimu</h3><ul><li><strong>Font:</strong> Mabadiliko ya herufi — ukubwa, rangi, bold, italic</li><li><strong>Borders:</strong> Mistari ya kutenganisha cells — muhimu kwa meza nzuri</li><li><strong>Fill Color:</strong> Rangi ya nyuma ya cell — inatumika kuonyesha vichwa vya meza</li><li><strong>Number Format:</strong> Currency (TZS), Percentage (%), Decimal places</li></ul><h3>Merge na Center</h3><p>Unaweza kuunganisha cells nyingi kuwa moja — muhimu kwa vichwa vya meza vikubwa. Chagua cells → Home → Merge &amp; Center.</p><blockquote><strong>Tip ya Kitaalamu:</strong> Tumia <strong>Format Painter</strong> (ndoo ya rangi kwenye Home tab) kunakili formatting kutoka cell moja hadi nyingine bila kufanya manual kila wakati.</blockquote>');
        $this->assignment($l, 'Meza ya Matumizi ya Kila Siku', 'Unda meza ya matumizi yako ya wiki moja na columns hizi: Tarehe, Aina ya Matumizi, Kiasi (TZS), Maelezo. Weka angalau safu 10. Format: (1) Kichwa cha meza — bold na background ya bluu, (2) Nambari katika format ya currency, (3) Borders kwa meza nzima, (4) Alternate row colors (kila safu nyingine rangi tofauti). Wasilisha .xlsx', 40, 5);

        $l = $this->lesson($m1, 3, 'Formulas za Msingi: SUM, AVERAGE, COUNT', 'Jifunza jinsi ya kuandika formulas — SUM, AVERAGE, COUNT, MAX, MIN. Msingi wa Excel calculations.', 1080,
            [['video_youtube', 'Basic Formulas - SUM, AVERAGE, COUNT', 'https://www.youtube.com/watch?v=QFOA9uDvn4s']],
            '<h2>Formulas za Msingi katika Excel</h2><p>Formula katika Excel inaanza na ishara ya <code>=</code>. Bila hiyo, Excel itaona kitu ulichoandika kama text tu.</p><h3>Functions Muhimu za Msingi</h3><ul><li><code>=SUM(A1:A10)</code> — Jumla ya nambari katika range A1 hadi A10</li><li><code>=AVERAGE(A1:A10)</code> — Wastani wa nambari</li><li><code>=COUNT(A1:A10)</code> — Hesabu ya cells zenye nambari</li><li><code>=COUNTA(A1:A10)</code> — Hesabu ya cells zote zenye thamani (text au nambari)</li><li><code>=MAX(A1:A10)</code> — Nambari kubwa zaidi katika range</li><li><code>=MIN(A1:A10)</code> — Nambari ndogo zaidi katika range</li></ul><h3>AutoSum</h3><p>Badala ya kuandika formula, chagua cell chini ya nambari zako kisha bonyeza <code>Alt + =</code>. Excel itaandika SUM formula moja kwa moja!</p><h3>Absolute vs Relative References</h3><p>Kawaida cell references ni <em>relative</em> — zinabadilika unaponakili formula. Tumia <code>$</code> kufanya <em>absolute</em>: <code>=$A$1</code> haitabadilika kamwe.</p><blockquote><strong>Kumbuka:</strong> Kila formula inaweza kutumia ranges (A1:A10), cells nyingi (A1,B1,C1), au maumbile mchanganyiko (A1:A5,C1:C5).</blockquote>');
        $this->assignment($l, 'Kazi ya Mwanzo: Bajeti ya Mwezi', 'Tengeneza spreadsheet ya bajeti ya familia yako kwa mwezi mmoja. Weka categories: Chakula, Usafiri, Kodi, Burudani, Afya, Elimu. Kwa kila category weka: Kiasi kilichopangwa na Kiasi kilichotumika. Tumia SUM, AVERAGE, MAX, MIN kuchambua bajeti yako. Onyesha tofauti (Variance) kati ya kilichopangwa na kilichotumika. Wasilisha kama Excel file (.xlsx)', 50, 7);

        // MODULE 2
        $m2 = $this->mod($course, 2, 'Functions za Nguvu (Power Functions)', 'VLOOKUP, IF, COUNTIF — functions ambazo zinatumika kila siku katika biashara.');

        $l = $this->lesson($m2, 1, 'Logical Functions: IF, AND, OR', 'Jifunza IF statement — jinsi ya kuamua kati ya matokeo mawili kulingana na hali. AND na OR kwa masharti mengi.', 1200,
            [['video_youtube', 'Excel IF Function - Mfano wa Kweli', 'https://www.youtube.com/watch?v=3YMHhZHJzb4']],
            '<h2>Logical Functions: IF, AND, OR</h2><p>Logical functions zinafanya Excel "fikirie" — zinaamua kati ya matokeo mawili au zaidi kulingana na masharti.</p><h3>IF Function</h3><p>Muundo: <code>=IF(sharti, thamani_kama_kweli, thamani_kama_uongo)</code></p><p>Mfano: <code>=IF(B2&gt;=50, "Amefaulu", "Ameshindwa")</code> — ukipata 50 au zaidi unafaulu.</p><h3>Nested IF (IF ndani ya IF)</h3><p><code>=IF(B2&gt;=80, "A", IF(B2&gt;=60, "B", IF(B2&gt;=50, "C", "F")))</code> — kutoa daraja la A, B, C, au F.</p><h3>AND na OR</h3><ul><li><code>=AND(A1&gt;0, B1&gt;0)</code> — kweli KAMA ZOTE ni kweli</li><li><code>=OR(A1&gt;0, B1&gt;0)</code> — kweli kama MOJA AU ZAIDI ni kweli</li><li><code>=IF(AND(A1&gt;=18, B1="Active"), "Eligible", "Not Eligible")</code> — mchanganyiko</li></ul><blockquote><strong>Tip:</strong> Ukitumia IF nyingi sana (zaidi ya 3), fikiria kutumia IFS function (Excel 2019+) ambayo ni rahisi kusoma: <code>=IFS(B2&gt;=80,"A", B2&gt;=60,"B", B2&gt;=50,"C", TRUE,"F")</code></blockquote>');
        $this->assignment($l, 'Mfumo wa Tathmini ya Wanafunzi', 'Unda spreadsheet ya wanafunzi 15 yenye columns: Jina, Alama za Mtihani 1, Alama za Mtihani 2, Wastani, Daraja, Hali. Tumia IF/AND/OR: Wastani = AVERAGE ya mitihani miwili. Daraja: A(≥80), B(≥65), C(≥50), F(<50). Hali: Amefaulu au Ameshindwa (kizingiti 50). Wasilisha .xlsx', 60, 7);

        $l = $this->lesson($m2, 2, 'Lookup Functions: VLOOKUP na INDEX/MATCH', 'VLOOKUP ni moja ya functions muhimu zaidi katika Excel. Jifunza kutafuta data kutoka tables kubwa. INDEX/MATCH ni mbadala bora zaidi.', 1440,
            [['video_youtube', 'VLOOKUP Tutorial - Mwongozo Kamili', 'https://www.youtube.com/watch?v=d3BYVQ6xIE4']],
            '<h2>VLOOKUP na INDEX/MATCH</h2><p>VLOOKUP inakuruhusu kutafuta thamani katika safu wima ya kwanza ya table na kurudisha thamani kutoka safu wima nyingine ya row hiyo hiyo.</p><h3>VLOOKUP Muundo</h3><p><code>=VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup])</code></p><ul><li><strong>lookup_value:</strong> Unachotafuta (mfano: nambari ya bidhaa)</li><li><strong>table_array:</strong> Mahali table ipo (mfano: $A$1:$D$100)</li><li><strong>col_index_num:</strong> Safu wima ya 1, 2, 3... inayotaka jibu</li><li><strong>range_lookup:</strong> FALSE kwa mechi kamili (tumia hii daima!)</li></ul><h3>Mapungufu ya VLOOKUP</h3><ul><li>Inaweza kutafuta kushoto tu (safu ya kwanza)</li><li>Polepole kwa data kubwa sana</li><li>Inashindwa ukiingiza/kufuta columns</li></ul><h3>INDEX/MATCH — Mbadala Bora</h3><p><code>=INDEX(C2:C100, MATCH(F2, A2:A100, 0))</code> — inaweza kutafuta pande zote, haraka zaidi, na inafanya kazi hata ukiingiza columns mpya.</p><blockquote><strong>Ushauri:</strong> Katika Excel 365, tumia XLOOKUP badala yake: <code>=XLOOKUP(F2, A2:A100, C2:C100)</code> — rahisi zaidi na ina uwezo zaidi.</blockquote>');
        $this->assignment($l, 'Inventory Analysis kwa VLOOKUP', 'Pewa dataset ya bidhaa 50 (au unda yako mwenyewe na columns: ID, Jina, Bei ya Ununuzi, Bei ya Uuzaji). Katika sheet nyingine, fanya Invoice: mwanafunzi anaandika ID ya bidhaa tu, na Excel inapata Jina na Bei kiotomatiki kwa VLOOKUP. Hesabu Faida kwa kila bidhaa. Wasilisha .xlsx', 80, 10);

        $l = $this->lesson($m2, 3, 'Text Functions: TRIM, CONCATENATE, LEFT/RIGHT', 'Kushughulikia text data — kuunganisha, kukata, kusafisha spaces, kubadilisha UPPER/lower case.', 900,
            [['video_youtube', 'Excel Text Functions', 'https://www.youtube.com/watch?v=rgnvL9P4Q-I']],
            '<h2>Text Functions katika Excel</h2><p>Data kutoka systems nyingi inakuja na matatizo ya text — spaces za ziada, herufi kubwa/ndogo zisizosawa, nambari kama text. Functions hizi zinasaidia kusafisha data haraka.</p><h3>Functions Muhimu</h3><ul><li><code>=TRIM(A1)</code> — Ondoa spaces za ziada mwanzoni, mwishoni, na kati</li><li><code>=UPPER(A1)</code> — Badilisha kuwa HERUFI KUBWA ZOTE</li><li><code>=LOWER(A1)</code> — badilisha kuwa herufi ndogo zote</li><li><code>=PROPER(A1)</code> — Kila Neno Linaanza Na Herufi Kubwa</li><li><code>=LEN(A1)</code> — Idadi ya herufi (spaces zikihesabiwa)</li><li><code>=LEFT(A1, 3)</code> — Chukua herufi 3 kutoka kushoto</li><li><code>=RIGHT(A1, 4)</code> — Chukua herufi 4 kutoka kulia</li><li><code>=MID(A1, 3, 5)</code> — Chukua herufi 5 kuanzia nafasi ya 3</li></ul><h3>Kuunganisha Text</h3><ul><li><code>=CONCATENATE(A1, " ", B1)</code> — njia ya zamani</li><li><code>=A1&amp;" "&amp;B1</code> — njia ya mkato kwa &amp;</li><li><code>=TEXTJOIN(", ", TRUE, A1:A10)</code> — unganisha cells nyingi na separator</li></ul><blockquote><strong>Mfano wa Kweli:</strong> Jina kama "  hamisi selemani  " linaweza kusafishwa na kubadilishwa: <code>=PROPER(TRIM(A1))</code> → "Hamisi Selemani"</blockquote>');
        $this->assignment($l, 'Kusafisha Database ya Wateja', 'Pewa orodha ya wateja 30 (au unda yako) ambao majina yao yana matatizo: spaces za ziada, herufi ndogo/kubwa zisizolingana, nambari za simu ambazo zina dashes. Tumia TRIM, PROPER, SUBSTITUTE kusafisha data. Tenganisha Jina la Kwanza na Jina la Mwisho kwa LEFT, RIGHT, FIND. Wasilisha kabla na baada ya kusafisha.', 60, 7);

        $l = $this->lesson($m2, 4, 'SUMIF, COUNTIF, AVERAGEIF', 'Hesabu za masharti — jumla ya nambari zinazokidhi criteria fulani. Muhimu sana kwa ripoti za biashara.', 1080,
            [['video_youtube', 'SUMIF na COUNTIF Functions', 'https://www.youtube.com/watch?v=qZS-c_tq3IE']],
            '<h2>SUMIF, COUNTIF, AVERAGEIF — Hesabu za Masharti</h2><p>Functions hizi zinafanya hesabu kwa <strong>safu zinazokidhi sharti fulani tu</strong>. Ni muhimu sana katika ripoti za biashara.</p><h3>COUNTIF — Hesabu kwa Sharti</h3><p><code>=COUNTIF(range, criteria)</code></p><p>Mfano: <code>=COUNTIF(C2:C100, "Dar es Salaam")</code> — hesabu wateja wote kutoka Dar es Salaam.</p><h3>SUMIF — Jumla kwa Sharti</h3><p><code>=SUMIF(range, criteria, sum_range)</code></p><p>Mfano: <code>=SUMIF(B2:B100, "Chakula", D2:D100)</code> — jumla ya matumizi ya Chakula tu.</p><h3>AVERAGEIF</h3><p><code>=AVERAGEIF(range, criteria, average_range)</code> — wastani kwa sharti.</p><h3>Wildcards katika Criteria</h3><ul><li><code>"Dar*"</code> — inaanza na "Dar"</li><li><code>"*chai*"</code> — ina neno "chai" popote</li><li><code>"&gt;1000"</code> — zaidi ya 1000</li><li><code>"&lt;&gt;0"</code> — si sifuri</li></ul><h3>SUMIFS / COUNTIFS (Masharti Mengi)</h3><p><code>=SUMIFS(sum_range, range1, criteria1, range2, criteria2)</code> — jumla kwa masharti mawili au zaidi.</p><blockquote><strong>Mfano wa Biashara:</strong> <code>=SUMIFS(D2:D100, B2:B100, "Mauzo", C2:C100, "Januari")</code> — jumla ya mauzo ya Januari tu.</blockquote>');
        $this->assignment($l, 'Ripoti ya Mauzo kwa SUMIF/COUNTIF', 'Pewa dataset ya mauzo (au unda: columns — Tarehe, Bidhaa, Mkoa, Kiasi, Aina ya Malipo). Unda ripoti inayoonyesha: (1) Jumla ya mauzo kwa kila mkoa kwa SUMIF, (2) Idadi ya miamala kwa kila aina ya malipo, (3) Wastani wa mauzo kwa kila bidhaa, (4) Jumla ya mauzo ya bidhaa fulani katika mkoa fulani (SUMIFS). Wasilisha .xlsx', 70, 8);

        // MODULE 3
        $m3 = $this->mod($course, 3, 'Data Analysis na Visualization', 'PivotTables, charts, conditional formatting — jinsi ya kuwasilisha data kwa njia inayoeleweka.');

        $l = $this->lesson($m3, 1, 'PivotTables — Uchambuzi wa Data Haraka', 'PivotTable ni chombo chenye nguvu zaidi katika Excel. Jifunza kuunda, kuformat, na kutumia PivotTables kuchambua data kubwa kwa sekunde chache.', 1800,
            [['video_youtube', 'PivotTables - Mwongozo wa Kweli', 'https://www.youtube.com/watch?v=UsdedFoTA68']],
            '<h2>PivotTables — Chombo cha Uchambuzi wa Data</h2><p>PivotTable inakuruhusu kuchambua data kubwa haraka sana bila kuandika formulas. Inafanya hesabu za kujumlisha, kuhesabu, na kupanga upya data kwa mabofyo machache tu.</p><h3>Jinsi ya Kuunda PivotTable</h3><ol><li>Chagua data yako (bonyeza cell yoyote ndani ya data)</li><li>Insert → PivotTable</li><li>Chagua mahali pa kuweka PivotTable (sheet mpya au sheet hiyo)</li><li>Buruta fields kutoka panel ya kulia hadi Rows, Columns, Values, Filters</li></ol><h3>Sehemu za PivotTable</h3><ul><li><strong>Rows:</strong> Kategoria unayotaka kuorodheshwa upande wa kushoto (mfano: Mkoa)</li><li><strong>Columns:</strong> Kategoria kwenye kichwa (mfano: Mwezi)</li><li><strong>Values:</strong> Nambari unayotaka kuhesabu (mfano: SUM ya Mauzo)</li><li><strong>Filters:</strong> Filter yote kwa wakati mmoja (mfano: Mwaka)</li></ul><h3>PivotTable Slicers</h3><p>PivotTable → Analyze → Insert Slicer — inaongeza vifungo vya kuchuja data kwa urahisi zaidi. Slicer zinafanya PivotTable kuwa interactive.</p><blockquote><strong>Muhimu:</strong> Ukiongeza data mpya, bonyeza-click PivotTable → Refresh ili isasishwe. Au tumia Power Query kama chanzo cha data — itasasishwa kiotomatiki.</blockquote>');
        $this->assignment($l, 'Uchambuzi wa Mauzo kwa PivotTable', 'Pewa dataset ya mauzo ya miaka 2 (au unda yenye safu 200+: Tarehe, Bidhaa, Mkoa, Mauzo, Gharama). Unda PivotTables 3: (1) Jumla ya mauzo kwa kila mkoa na mwezi, (2) Top 5 bidhaa zinazouza vizuri, (3) Linganisha mauzo ya mwaka 1 vs mwaka 2. Ongeza Slicers. Wasilisha .xlsx', 80, 10);

        $l = $this->lesson($m3, 2, 'Charts na Graphs za Kitaalamu', 'Column charts, line charts, pie charts, bar charts. Jinsi ya kuchagua chart inayofaa data yako na kuiformat kwa hali ya juu.', 1200,
            [['video_youtube', 'Excel Charts na Graphs', 'https://www.youtube.com/watch?v=DAU0qqh_I-A']],
            '<h2>Charts na Graphs za Kitaalamu katika Excel</h2><p>Chart nzuri inaweza kuwasilisha habari ngumu kwa sekunde moja. Chaguo baya la chart linaweza kupotosha wasomaji. Jifunza kuchagua chart sahihi.</p><h3>Aina za Charts na Matumizi Yao</h3><ul><li><strong>Column/Bar Chart:</strong> Kulinganisha kategoria — mauzo kwa mkoa, matumizi kwa mwezi</li><li><strong>Line Chart:</strong> Kuonyesha mwelekeo kwa muda — bei ya bidhaa, ukuaji wa kampuni</li><li><strong>Pie/Doughnut Chart:</strong> Kuonyesha sehemu ya jumla — 5 kategoria au chini tu!</li><li><strong>Scatter Plot:</strong> Kuonyesha uhusiano kati ya vitu viwili</li><li><strong>Area Chart:</strong> Kama line chart lakini inajaza eneo chini</li></ul><h3>Kuunda Chart Nzuri</h3><ol><li>Chagua data → Insert → Charts</li><li>Ongeza Chart Title inayoelezea vizuri</li><li>Label axes (Axis Titles) kwa wazi</li><li>Tumia rangi tofauti inayoonekana vizuri (avoid 3D charts!)</li><li>Ondoa gridlines nyingi — zinachanganya</li></ol><blockquote><strong>Kanuni ya Dhahabu:</strong> Chart nzuri inaeleweka bila maelezo yoyote ya ziada. Ukihitaji kueleza chart yako kwa maneno mengi, ibunifu upya.</blockquote>');
        $this->assignment($l, 'Visualization ya Data ya Biashara', 'Kutumia dataset uliyounda awali, unda charts 4 tofauti: (1) Column chart ya mauzo kwa mwezi (na data labels), (2) Line chart ya mwelekeo wa mauzo ya miaka 2, (3) Pie chart ya sehemu ya kila mkoa (top 5 tu), (4) Combo chart (Column + Line) inayoonyesha Mauzo na Faida pamoja. Format kila chart kwa hali ya juu — colors, titles, labels. Wasilisha .xlsx', 80, 10);

        $l = $this->lesson($m3, 3, 'Conditional Formatting', 'Weka rangi za moja kwa moja kulingana na thamani za data. Heat maps, data bars, icon sets — kuona patterns haraka.', 900,
            [['video_youtube', 'Conditional Formatting kwa Undani', 'https://www.youtube.com/watch?v=TtcSK_e67SM']],
            '<h2>Conditional Formatting — Rangi Zinazofanya Kazi</h2><p>Conditional Formatting inaweka rangi, icons, au data bars kwenye cells moja kwa moja kulingana na thamani zao. Inakusaidia kuona matatizo na mwelekeo haraka bila kuchunguza nambari moja moja.</p><h3>Aina za Conditional Formatting</h3><ul><li><strong>Highlight Cell Rules:</strong> Rangi kwa cells zinazokidhi sharti (zaidi ya 1000, kati ya 50-100, nk)</li><li><strong>Top/Bottom Rules:</strong> Angazia Top 10%, Bottom 10, Above Average</li><li><strong>Data Bars:</strong> Bar ndogo ndani ya cell — onyesha ukubwa wa kiasi</li><li><strong>Color Scales:</strong> Mabadiliko ya rangi — kijani (juu) hadi nyekundu (chini) — perfect kwa heat maps</li><li><strong>Icon Sets:</strong> Mishale, alama za traffic light, nyota — kuonyesha hali haraka</li></ul><h3>Custom Rules</h3><p>Home → Conditional Formatting → New Rule → "Use a formula to determine which cells to format"</p><p>Mfano: <code>=B2&lt;C2</code> — weka nyekundu safu zote ambapo mauzo ya halisi ni chini ya lengo.</p><blockquote><strong>Matumizi ya Kweli:</strong> Weka alama ya traffic light (icon set) kwenye ripoti ya mauzo — nyekundu = pungufu ya 50% ya lengo, njano = 50-80%, kijani = 80%+. Waambie wakurugenzi haraka bila kuhitaji kusoma nambari!</blockquote>');
        $this->assignment($l, 'Ripoti ya KPI na Conditional Formatting', 'Unda ripoti ya KPI ya idara 5 na metrics 4 kila moja (Mauzo, Wateja Wapya, Faida, Malalamiko). Weka: (1) Color scale kwa mauzo (kijani=juu, nyekundu=chini), (2) Icon set (traffic light) kwa hali ya lengo, (3) Highlight kwa nyekundu safu zote ambazo hazijakidhi lengo, (4) Data bars kwa Wateja Wapya. Wasilisha .xlsx', 60, 7);

        $l = $this->lesson($m3, 4, 'Dashboard ya Excel — Mradi wa Mwisho', 'Unganisha PivotTables, charts, na slicers kuunda dashboard ya kitaalamu ambayo inasasishwa moja kwa moja unapoongeza data.', 2400,
            [['video_youtube', 'Excel Dashboard Tutorial', 'https://www.youtube.com/watch?v=K74_FNs6dsE']],
            '<h2>Dashboard ya Excel — Mradi wa Mwisho</h2><p>Dashboard nzuri ya Excel ni ukurasa mmoja unaotoa picha kamili ya biashara yako. Inaunganisha PivotTables, charts, KPI cards, na slicers kuunda chombo cha maamuzi ya haraka.</p><h3>Hatua za Kuunda Dashboard</h3><ol><li><strong>Andaa Data:</strong> Data yako iwe katika Excel Table (Ctrl+T) — itasasisha charts moja kwa moja</li><li><strong>Unda PivotTables:</strong> Sheets tofauti kwa kila uchunguzi</li><li><strong>Unda Charts:</strong> Kutoka PivotTables — ziunganishwe, zisasishwe pamoja</li><li><strong>Design Dashboard Sheet:</strong> Sheet safi, background ya giza au nyeupe</li><li><strong>Link Charts:</strong> Nakili charts na uziweke kwenye dashboard sheet</li><li><strong>Ongeza Slicers:</strong> Unganisha slicers na PivotTables zote — click moja inasasisha kila kitu</li></ol><h3>Tips za Design</h3><ul><li>Weka KPI cards juu (Jumla ya Mauzo, Faida, Wateja)</li><li>Fuata mpangilio: muhimu zaidi juu-kushoto</li><li>Tumia rangi 2-3 tu — usizidishe</li><li>Ficha gridlines (View → uncheck Gridlines)</li><li>Lock cells za dashboard — wachache tu wanaweza kubadilisha</li></ul><blockquote><strong>Lengo la Mwisho:</strong> Dashboard nzuri inafanya CEO aweze kuona hali ya kampuni yake ndani ya sekunde 30. Ndiyo kipimo cha ubora wa dashboard yako.</blockquote>');
        $this->assignment($l, 'Sales Dashboard Kamili', 'Pewa dataset ya mauzo ya mwaka mzima (miezi 12, mkoa 5, bidhaa 10+). Unda dashboard kamili inayoonyesha: (1) KPI cards — Jumla ya Mauzo, Faida, Wateja Wapya, (2) Line chart ya mwelekeo wa mauzo ya miezi 12, (3) Bar chart ya mauzo kwa mkoa, (4) Pie chart ya sehemu ya bidhaa, (5) Slicers za Mwezi na Mkoa. Kila kitu kisasishwe ukibonyeza slicer. Wasilisha .xlsx', 100, 14);
    }

    // =========================================================================
    // COURSE 2 — Power Query & Data Transformation
    // =========================================================================
    private function powerQueryCourse(int $trainerId): void
    {
        $course = Course::updateOrCreate(
            ['title' => 'Power Query: Ubadilishaji wa Data kwa Ufanisi'],
            [
                'description'    => 'Power Query ni chombo cha kisasa cha kuunganisha, kusafisha, na kubadilisha data kutoka vyanzo vingi. Jifunza kuautomatisha kazi za data zitakazochukua masaa kwa dakika chache tu.',
                'category'       => 'power_query',
                'level'          => 'intermediate',
                'duration_hours' => 14,
                'price_tzs'      => 0,
                'instructor_id'  => $trainerId,
                'created_by'     => $trainerId,
                'status'         => 'published',
                'published_at'   => now(),
                'approved_at'    => now(),
            ]
        );

        $m1 = $this->mod($course, 1, 'Kuanza na Power Query', 'Introduction, interface, na kuunganisha na vyanzo vya data — Excel, CSV, na databases.');

        $l = $this->lesson($m1, 1, 'Power Query ni Nini na Kwa Nini Itumie?', 'Tofauti kati ya kufanya kazi kwa mkono na kwa Power Query. Mifano ya kweli ya biashara ambapo Power Query inaokoa wakati.', 900,
            [['video_youtube', 'Intro ya Power Query - Badilisha Jinsi Unavyofanya Kazi', 'https://www.youtube.com/watch?v=0aeZX1l4JT4']],
            '<h2>Power Query — Mapinduzi ya Kufanya Kazi na Data</h2><p>Power Query ni chombo cha Excel na Power BI kinachokuruhusu kupakia, kusafisha, na kubadilisha data kutoka vyanzo vingi bila kuandika macros au code ngumu.</p><h3>Tatizo Ambalo Power Query Inasuluhisha</h3><p>Kila mwezi unafanya hivi kwa mkono: (1) Download ripoti kutoka ERP, (2) Safisha data kwa mkono — ondoa spaces, format tarehe, (3) Unganisha sheets kadhaa, (4) Tengeneza ripoti ya mwisho. Inachukua masaa 4-8. Kwa Power Query: bonyeza <strong>Refresh</strong> mara moja — dakika 2 tu!</p><h3>Faida Kuu za Power Query</h3><ul><li><strong>Reproducible:</strong> Kila hatua inarekodiwa — unaweza kuirudia bila kusahau hatua yoyote</li><li><strong>Updatable:</strong> Data mpya inaingia — bonyeza Refresh tu</li><li><strong>Auditable:</strong> Meneja wako anaweza kuona kila hatua uliyofanya</li><li><strong>Scalable:</strong> Inafanya kazi na rows 100 au milioni 10</li></ul><h3>Wapi Kupata Power Query</h3><p>Excel 2016+: Data tab → Get Data. Power BI Desktop: Home → Get Data. Inafanya kazi sawa katika zote mbili.</p><blockquote><strong>Ukweli wa Biashara:</strong> Wataalamu wa data wanasema 80% ya muda wao unakwenda katika kusafisha data. Power Query inabadilisha hilo kabisa.</blockquote>');
        $this->assignment($l, 'Tathmini ya Power Query dhidi ya Manual', 'Pewa dataset ya mauzo ya miezi 3 (files 3 za CSV). Kwanza, unganisha kwa mkono katika Excel (copy-paste) na rekodi muda uliochukua. Kisha, unganisha kwa Power Query (Append Queries). Linganisha: (1) Muda uliotumika, (2) Hatua ulizofanya, (3) Jinsi unavyosasisha data mpya. Andika ripoti fupi ya matokeo. Wasilisha .xlsx + ripoti (.docx)', 50, 5);

        $l = $this->lesson($m1, 2, 'Kuunganisha CSV, Excel, na Folders', 'Jinsi ya kupakua data kutoka CSV file, Excel file, na folder nzima ya files. Auto-refresh ya data.', 1200,
            [['video_youtube', 'Power Query - Kuunganisha Vyanzo vya Data', 'https://www.youtube.com/watch?v=KxQn6MFbUyM']],
            '<h2>Kuunganisha Vyanzo vya Data katika Power Query</h2><p>Power Query inaweza kupakia data kutoka mahali popote — faili ya Excel, CSV, folder nzima, database, au hata website. Hii ndio nguvu yake kubwa.</p><h3>Aina za Vyanzo vya Data</h3><ul><li><strong>Excel Workbook:</strong> Data → Get Data → From File → From Excel Workbook</li><li><strong>CSV/Text:</strong> Data → Get Data → From File → From Text/CSV</li><li><strong>Folder:</strong> Data → Get Data → From File → From Folder — inapakia files ZOTE katika folder moja kiotomatiki</li><li><strong>Web:</strong> Data → Get Data → From Other Sources → From Web — inasoma tables kutoka websites</li></ul><h3>Kupakia Folder Nzima</h3><p>Hii ni nguvu ya kipekee ya Power Query. Ukiweka files zako zote katika folder moja (mfano: "Mauzo_2024"), Power Query itazipakia zote na kuziunganisha — hata ukiongeza file mpya, Refresh itaipakia pia!</p><h3>Kurekebisha Data Source</h3><p>Ukihamisha files au kubadilisha jina la folder: Data → Queries &amp; Connections → bonyeza-click query → Edit → Home → Data Source Settings.</p><blockquote><strong>Tip:</strong> Weka files zako zote katika OneDrive/SharePoint folder. Power Query itapakua data mpya kiotomatiki kila unapofungua Excel na kubonyeza "Enable Content".</blockquote>');
        $this->assignment($l, 'Unganisha Files Nyingi za CSV', 'Unda folder yenye files 4 za CSV (au zipata kutoka mtandao): kila moja ina mauzo ya robo mwaka moja. Tumia Power Query Folder connector kuziunganisha kuwa table moja. Ongeza column "Chanzo" inayoonyesha jina la file asili. Hakikisha query inafanya kazi ukiongeza file ya 5. Wasilisha .xlsx na Power Query steps zikiwa wazi.', 60, 7);

        $l = $this->lesson($m1, 3, 'Basic Transformations: Filter, Sort, Rename', 'Kuchuja safu, kupanga, kubadilisha majina ya columns. Kila hatua inarekodiwa na inaweza kubadilishwa baadaye.', 1080,
            [['video_youtube', 'Power Query Basic Transformations', 'https://www.youtube.com/watch?v=7q9aFKGXFXE']],
            '<h2>Mabadiliko ya Msingi katika Power Query Editor</h2><p>Power Query Editor ndio mahali ambapo unabadilisha data yako. Kila hatua unayofanya inaonekana kwenye panel ya "Applied Steps" upande wa kulia — unaweza kuihariri au kuifuta wakati wowote.</p><h3>Mabadiliko Muhimu ya Msingi</h3><ul><li><strong>Rename Column:</strong> Double-click jina la column → andika jina jipya</li><li><strong>Change Data Type:</strong> Bonyeza ikoni ya ABC/123 kando ya jina la column</li><li><strong>Filter Rows:</strong> Bonyeza dropdown ya column → uncheck thamani usizotaka</li><li><strong>Sort:</strong> Bonyeza dropdown → Sort Ascending/Descending</li><li><strong>Remove Columns:</strong> Chagua columns usizotaka → Right-click → Remove Columns</li><li><strong>Remove Duplicates:</strong> Home → Remove Rows → Remove Duplicates</li><li><strong>Remove Blank Rows:</strong> Home → Remove Rows → Remove Blank Rows</li></ul><h3>Trim na Clean</h3><p>Transform → Format → Trim (ondoa spaces za ziada) na Clean (ondoa herufi zisizoonekana). Tumia hizi DAIMA ukipakia data kutoka mfumo wa nje.</p><h3>Applied Steps Panel</h3><p>Kila hatua unayofanya inaonekana kama step inayoweza kuhaririwa. Ukibonyeza step yoyote, utaona data ilivyokuwa katika hatua hiyo. Hii ni nguvu kubwa ya Power Query.</p><blockquote><strong>Kanuni:</strong> Badilisha aina ya data (data types) mara moja baada ya kupakia data — kabla ya mabadiliko yoyote. Hii inazuia makosa ya hesabu baadaye.</blockquote>');
        $this->assignment($l, 'Kusafisha Dataset ya Wafanyakazi', 'Pewa au unda dataset ya wafanyakazi 50 na matatizo mengi: majina yenye spaces, safu wima za tarehe kama text, mshahara ulioandikwa kama "TZS 500,000" (text), idara zenye herufi kubwa/ndogo zisizolingana. Tumia Power Query kusafisha KILA tatizo. Wasilisha step ya mwanzo (data chafu) na mwisho (data safi) + Applied Steps zote visible.', 70, 8);

        $m2 = $this->mod($course, 2, 'Mabadiliko ya Kina (Advanced Transformations)', 'Merge, append, unpivot, custom columns — zana za kubadilisha data ngumu.');

        $l = $this->lesson($m2, 1, 'Merge Queries — Kuunganisha Tables', 'Kama VLOOKUP lakini kwa nguvu zaidi. Aina zote za joins: left, right, inner, outer. Mfano wa kweli wa biashara.', 1440,
            [['video_youtube', 'Power Query Merge Queries', 'https://www.youtube.com/watch?v=Dp8yd7RoEbk']],
            '<h2>Merge Queries — VLOOKUP ya Power Query</h2><p>Merge Queries inafanya kazi kama VLOOKUP — inaunganisha tables mbili kwa column inayofanana. Lakini ni bora zaidi: inaweza kuunganisha kwa columns nyingi na ina aina zote za SQL joins.</p><h3>Aina za Joins</h3><ul><li><strong>Left Outer Join:</strong> Safu ZOTE kutoka table ya kushoto, zinazolingana tu kutoka table ya kulia (hii ni kawaida zaidi)</li><li><strong>Right Outer Join:</strong> Kinyume — safu zote kutoka table ya kulia</li><li><strong>Inner Join:</strong> Safu zinazolingana ZOTE MBILI tu</li><li><strong>Full Outer Join:</strong> Safu zote kutoka tables zote mbili</li><li><strong>Left Anti Join:</strong> Safu kutoka table ya kushoto ambazo HAZIPO katika table ya kulia (muhimu kwa tofauti)</li></ul><h3>Jinsi ya Kufanya Merge</h3><ol><li>Pakia tables zote mbili kwenye Power Query</li><li>Chagua query ya kwanza → Home → Merge Queries</li><li>Chagua column inayofanana kutoka kila table</li><li>Chagua aina ya join</li><li>Expand column mpya iliyoundwa — chagua columns unazotaka</li></ol><blockquote><strong>Tofauti na VLOOKUP:</strong> Merge inaweza kutumia columns nyingi kama key (mfano: Jina + Tarehe), inafanya kazi na data kubwa haraka zaidi, na haisimami ukiongeza columns mpya kwenye table.</blockquote>');
        $this->assignment($l, 'Unganisha Mauzo na Database ya Bidhaa', 'Una tables mbili: (1) Mauzo (Nambari ya Oda, ID ya Bidhaa, Idadi, Tarehe), (2) Bidhaa (ID, Jina, Bei ya Msingi, Kategoria). Fanya Merge kuziunganisha. Hesabu: Jumla ya Mauzo (Idadi × Bei). Tumia Left Anti Join kupata bidhaa ambazo hazikuuzwa kabisa. Wasilisha .xlsx.', 80, 10);

        $l = $this->lesson($m2, 2, 'Append Queries — Kuunganisha Safu mlalo', 'Kuchanganya data kutoka tables nyingi kuwa moja. Mfano: ripoti za mauzo za miezi 12 tofauti kuwa moja.', 1200,
            [['video_youtube', 'Append Queries kwa Undani', 'https://www.youtube.com/watch?v=sxSZL3oyMJ4']],
            '<h2>Append Queries — Unganisha Tables Moja chini ya Nyingine</h2><p>Append Queries inaunganisha tables "wima" — inaweka safu za table moja chini ya table nyingine. Hii ndio tofauti na Merge (inayounganisha "mlalo").</p><h3>Lini Kutumia Append</h3><ul><li>Files za mwezi 12 za mauzo — unaziunganisha kuwa table moja ya mwaka</li><li>Data kutoka maeneo/matawi tofauti yenye muundo sawa</li><li>Kuchanganya data ya zamani na mpya katika database moja</li></ul><h3>Append vs Union</h3><p>Append ya Power Query inafanya kazi kama SQL UNION ALL — inachukua safu zote hata duplicates. Ukitaka unique rows tu, ongeza "Remove Duplicates" baada ya Append.</p><h3>Append ya Files Nyingi</h3><p>Njia bora: Tumia Folder connector (tuliyoijifunza awali) — Power Query itaziappend zote kiotomatiki badala ya kuziappend moja moja kwa mikono.</p><h3>Kushughulikia Columns Tofauti</h3><p>Ukiwa na tables ambazo columns zao hazilingani kabisa, Power Query itaunda column kwa kila jina tofauti na kuweka null kwa tables ambazo hazina column hiyo.</p><blockquote><strong>Mbinu ya Kitaalamu:</strong> Append queries katika Power Query inafanya kazi bora zaidi ukiziweka katika Parameter table — unaweza kubadilisha muda wa data (mfano: mwaka) bila kuhariri query.</blockquote>');
        $this->assignment($l, 'Ripoti ya Mwaka Kutoka Files za Kila Mwezi', 'Unda (au pewa) files 12 za CSV — kila moja ina mauzo ya mwezi mmoja na columns: Tarehe, Bidhaa, Mkoa, Kiasi. Tumia Power Query Folder connector kuziappend zote. Ongeza column ya "Mwezi" iliyotokana na jina la file. Unda pivot table kutoka data iliyounganishwa. Jaribu kuongeza file ya mwezi 13 — itaonekana baada ya Refresh? Wasilisha .xlsx.', 75, 10);

        $l = $this->lesson($m2, 3, 'Unpivot — Kubadilisha Columns kuwa Rows', 'Data pivot vs unpivot — muhimu sana kwa data ambayo imepangwa vibaya. Mfano: kubadilisha ripoti ya kawaida iwe tayari kwa PivotTable.', 1080,
            [['video_youtube', 'Unpivot Data kwa Power Query', 'https://www.youtube.com/watch?v=3ZGm5HC70vI']],
            '<h2>Unpivot — Kubadilisha "Wide" Data kuwa "Tall" Data</h2><p>Mara nyingi data inakuja katika muundo wa "wide" — kila mwezi ni column yake. Hii ni nzuri kwa kuona, lakini mbaya kwa analysis. Power Query inaweza kubadilisha muundo huu kwa sekunde chache.</p><h3>Tatizo la Kawaida</h3><p>Una ripoti hii:</p><pre>Bidhaa | Januari | Februari | Machi\nChakula | 500K | 480K | 520K\nUsafiri | 200K | 210K | 190K</pre><p>PivotTable haiwezi kuchambua vizuri — ungependa muundo huu:</p><pre>Bidhaa | Mwezi | Kiasi\nChakula | Januari | 500K\nChakula | Februari | 480K</pre><h3>Jinsi ya Kufanya Unpivot</h3><ol><li>Chagua columns ambazo HAZITABADILIKA (mfano: column ya Bidhaa)</li><li>Transform → Unpivot Other Columns</li><li>Power Query itabadilisha columns nyingine zote kuwa rows mbili: "Attribute" na "Value"</li><li>Badilisha majina: Attribute → Mwezi, Value → Kiasi</li></ol><h3>Pivot (Kinyume)</h3><p>Transform → Pivot Column — inabadilisha rows kuwa columns. Tumia hii unapotaka kuunda ripoti ya "cross-tab" kutoka data ya "tall".</p><blockquote><strong>Kanuni ya Dhahabu ya Data:</strong> Data "safi" (tidy data) ina safu moja kwa kila uchunguzi na column moja kwa kila variable. Unpivot inakusaidia kufika hapo.</blockquote>');
        $this->assignment($l, 'Unpivot Ripoti ya Mauzo ya Robo Mwaka', 'Una ripoti ya Excel yenye muundo huu: Mkoa | Q1 | Q2 | Q3 | Q4 (kila moja ni Kiasi cha Mauzo). Tumia Power Query: (1) Unpivot columns Q1-Q4 kuwa rows, (2) Badilisha jina: Attribute→Robo, Value→Mauzo, (3) Ongeza column ya "Mwaka" = 2024, (4) Unda PivotTable kutoka data mpya. Onyesha kuwa PivotTable sasa inafanya kazi vizuri. Wasilisha .xlsx.', 70, 8);

        $l = $this->lesson($m2, 4, 'Custom Columns na M Language Basics', 'Andika formulas zako za Power Query (M Language). Kutengeneza columns mpya kwa kuhesabu au kubadilisha data.', 1440,
            [['video_youtube', 'M Language Basics kwa Beginners', 'https://www.youtube.com/watch?v=e4IQ80nXUqc']],
            '<h2>Custom Columns na M Language katika Power Query</h2><p>M Language ni lugha inayoendeshea Power Query nyuma ya pazia. Kila hatua unayofanya katika Power Query Editor inabadilishwa kuwa M code. Kujua M Language kunakupa nguvu zaidi ya kubadilisha data.</p><h3>Custom Column (bila M Language)</h3><p>Add Column → Custom Column → andika formula yako.</p><p>Mfano: <code>[Mauzo] - [Gharama]</code> → inaunda column ya Faida.</p><h3>M Language — Misingi</h3><ul><li><strong>Text:</strong> <code>"Habari"</code> (alama za nukta mbili)</li><li><strong>Number:</strong> <code>42</code> au <code>3.14</code></li><li><strong>Boolean:</strong> <code>true</code> au <code>false</code></li><li><strong>Null:</strong> <code>null</code> (kwa thamani zilizokosekana)</li><li><strong>Conditional:</strong> <code>if [Mauzo] &gt; 1000 then "Kubwa" else "Ndogo"</code></li></ul><h3>Functions Muhimu za M</h3><ul><li><code>Text.Trim([Jina])</code> — ondoa spaces</li><li><code>Text.Upper([Jina])</code> — herufi kubwa</li><li><code>Number.Round([Bei], 2)</code> — peta nambari</li><li><code>Date.Year([Tarehe])</code> — toa mwaka</li><li><code>Date.Month([Tarehe])</code> — toa mwezi</li><li><code>Duration.Days([Tarehe Mwisho] - [Tarehe Mwanzo])</code> — tofauti ya siku</li></ul><blockquote><strong>Jinsi ya Kujifunza M:</strong> Fuata kila hatua unayofanya katika Power Query Editor, kisha bonyeza "Advanced Editor" kuona M code iliyoundwa. Hii ndiyo njia bora ya kujifunza M bila kuhitaji kujifunza kutoka sifuri.</blockquote>');
        $this->assignment($l, 'Data Cleaning kwa Custom Columns', 'Pewa dataset chafu ya wateja 200 (herufi kubwa/ndogo zisizolingana, spaces, tarehe katika format tofauti, bei kama text). Tumia Power Query na M Language: (1) Safisha majina kwa Text.Trim na Text.Proper, (2) Badilisha tarehe kutoka text kuwa Date, (3) Ondoa alama za sarafu kutoka bei (Text.Remove), (4) Hesabu umri wa wateja (Duration.Days), (5) Kategoria ya Wateja kwa if/else. Wasilisha .xlsx + M code ya kila hatua.', 90, 12);

        $m3 = $this->mod($course, 3, 'Power Query kwa Vitendo (Real-world)', 'Mradi wa mwisho na mbinu za kitaalamu za Production.');

        $l = $this->lesson($m3, 1, 'Kuunganisha na Database (SQL Server, SharePoint)', 'Jinsi ya kuunganisha Power Query na SQL Server, SharePoint, na vyanzo vya web. Refresh ya moja kwa moja.', 1200,
            [['video_youtube', 'Power Query na Database Connection', 'https://www.youtube.com/watch?v=s8oLi_JLMLA']],
            '<h2>Power Query na Vyanzo vya Data vya Biashara</h2><p>Katika mazingira ya biashara, data haikaa katika files za Excel — iko katika databases, SharePoint, web APIs, na mifumo ya ERP. Power Query inaweza kuunganisha na vyanzo hivi vyote.</p><h3>SQL Server</h3><p>Data → Get Data → From Database → From SQL Server Database. Ingiza: Server name, Database name. Unaweza kuandika SQL query moja kwa moja au kuchagua table.</p><h3>SharePoint Online</h3><p>Data → Get Data → From Online Services → From SharePoint Online List. Ingiza URL ya SharePoint site yako. Muhimu sana kwa kampuni zinazotumia Microsoft 365.</p><h3>Web (HTTP)</h3><p>Data → Get Data → From Other Sources → From Web. Ingiza URL ya data — inaweza kuwa JSON API, XML feed, au hata HTML table kutoka website.</p><h3>Scheduled Refresh katika Power BI</h3><p>Ukichapisha ripoti yako kwenye Power BI Service, unaweza kusetupia scheduled refresh — data inasasishwa kiotomatiki kila saa, siku, au wiki bila kufanya chochote.</p><blockquote><strong>Usalama:</strong> Pumzika na credentials zako! Power Query inaweza kuhifadhi username/password au kutumia Windows Authentication. Kwa data nyeti, tumia mazingira ya enterprise authentication badala ya kuweka passwords moja kwa moja.</blockquote>');
        $this->assignment($l, 'Unganisha Web Data na Excel', 'Tumia Power Query From Web kupakia data kutoka URL ya umma (mfano: meza ya data kutoka Wikipedia, au data ya exchange rates). Safisha data iliyopakiwa, ongeza columns muhimu, na uunde ripoti. Onyesha kwamba Refresh inasasisha data mpya. Wasilisha .xlsx na maelezo ya URL uliyotumia.', 70, 8);

        $l = $this->lesson($m3, 2, 'Error Handling na Troubleshooting', 'Jinsi ya kushughulikia makosa katika Power Query bila kupoteza data. try...otherwise na error columns.', 900,
            [['video_youtube', 'Power Query Error Handling', 'https://www.youtube.com/watch?v=OLW6Md-3yOI']],
            '<h2>Error Handling katika Power Query</h2><p>Data ya kweli daima ina makosa — thamani zilizokosekana, aina za data zisizo sahihi, characters zisizo rasmi. Power Query ina zana nzuri za kushughulikia hali hizi bila kufuta data nzima.</p><h3>Aina za Makosa ya Kawaida</h3><ul><li><strong>Type Mismatch:</strong> Jaribu kubadilisha "abc" kuwa number</li><li><strong>Null Values:</strong> Thamani iliyokosekana — null katika M Language</li><li><strong>Division by Zero:</strong> Kugawanya na sifuri</li><li><strong>File Not Found:</strong> Path ya file imebadilika</li></ul><h3>try...otherwise</h3><p>Katika Custom Column: <code>try Number.FromText([Bei]) otherwise 0</code></p><p>Hii inajaribu kubadilisha [Bei] kuwa nambari. Ukishindwa (kwa sababu ni text kama "N/A"), inarudisha 0 badala ya error.</p><h3>Replace Errors</h3><p>Right-click column → Replace Errors — badilisha errors zote kuwa thamani uliyochagua (null, 0, "N/A").</p><h3>Remove Errors</h3><p>Home → Remove Rows → Remove Errors — futa safu zote zenye errors. Tumia hii kwa tahadhari — unapoteza data!</p><blockquote><strong>Mbinu Bora:</strong> Badala ya kufuta safu zenye errors, ongeza column ya "Data_Quality" inayoonyesha kama safu ina tatizo. Hii inakupa uwezo wa kuripoti tatizo badala ya kulifuta.</blockquote>');
        $this->assignment($l, 'Kushughulikia Dataset yenye Makosa', 'Pewa dataset yenye matatizo makubwa: nambari zilizoandikwa kama text, tarehe zisizo sahihi, null values nyingi, na division by zero hali. Tumia try...otherwise, Replace Errors, na Column ya Data Quality kupanga data nzuri dhidi ya chafu. Onyesha hesabu ya rows za tatizo na rows safi. Wasilisha .xlsx', 75, 8);

        $l = $this->lesson($m3, 3, 'Automated Monthly Reporting', 'Jenga mfumo wa ripoti za kila mwezi ambao unasasishwa kwa click moja. Unganisha data kutoka folders nyingi kiotomatiki.', 1800,
            [['video_youtube', 'Automated Reports na Power Query', 'https://www.youtube.com/watch?v=xhqFYaJfzFA']],
            '<h2>Automated Monthly Reporting — Mfumo wa Kitaalamu</h2><p>Lengo la mwisho la Power Query ni kuunda mfumo ambapo unaongeza file mpya kwenye folder — na ripoti yako inasasishwa kiotomatiki kwa kubonyeza Refresh. Hii inaokoa masaa ya kazi kila mwezi.</p><h3>Miundo ya Mfumo Bora</h3><ol><li><strong>Data Folder:</strong> Weka files zote za data katika folder moja (OneDrive au Shared Drive)</li><li><strong>Power Query:</strong> Folder connector → Append → Transform → Load</li><li><strong>Excel Tables:</strong> Data yote katika Named Tables — charts zinasasishwa moja kwa moja</li><li><strong>Dashboard Sheet:</strong> Charts na PivotTables zilizounganishwa na data</li><li><strong>Macro ya Refresh (optional):</strong> VBA button moja inayofanya Refresh yote</li></ol><h3>Parameters katika Power Query</h3><p>Unaweza kuunda Parameter (Data → New Query → Enter Data) kama "Mwaka Unaofanyiwa Ripoti" = 2024. Ukibadilisha parameter moja, data yote inachujwa kiotomatiki.</p><h3>Kutenganisha Majukumu</h3><ul><li><strong>Data folder:</strong> Wafanyakazi wa kawaida wanaweza kuongeza files</li><li><strong>Template Excel:</strong> Huwezi kubadilika — umeshaundwa vizuri</li><li><strong>Refresh:</strong> Mtu yeyote anaweza kubonyeza — hakuna ujuzi wa Power Query unaohitajika</li></ul><blockquote><strong>Mfano Halisi:</strong> Kampuni moja ya Tanzania iliokoa saa 6 kwa mwezi (masaa 72 kwa mwaka) kwa kutekeleza mfumo huu kwa ripoti yao ya fedha ya kila mwezi. Hii ni thamani ya kweli ya Power Query.</blockquote>');
        $this->assignment($l, 'Automated Report ya Kila Mwezi', 'Unda mfumo kamili wa Power Query unaounganisha mauzo ya miezi 12 (files 12 tofauti) kuwa ripoti moja. Mfumo unapaswa: (1) Kupakia files zote kutoka folder moja, (2) Kusafisha data kiotomatiki, (3) Kuunda PivotTable na Charts zinazosasishwa, (4) Kuwa tayari kwa mwezi wa 13 bila mabadiliko yoyote ya query. Dakika 2 kufanya refresh badala ya masaa 4 ya kufanya kwa mkono. Wasilisha .xlsx + maelezo ya mfumo.', 100, 14);
    }

    // =========================================================================
    // COURSE 3 — Power BI for Business Analytics
    // =========================================================================
    private function powerBiCourse(int $trainerId): void
    {
        $course = Course::updateOrCreate(
            ['title' => 'Power BI: Uchambuzi wa Biashara na Dashboards'],
            [
                'description'    => 'Jifunza Power BI kutoka mwanzo — kupakia data, kuunda measures za DAX, kutengeneza dashboards za kisasa, na kushiriki ripoti na timu yako. Chombo kinachotumika na makampuni makubwa duniani.',
                'category'       => 'power_bi',
                'level'          => 'intermediate',
                'duration_hours' => 20,
                'price_tzs'      => 0,
                'instructor_id'  => $trainerId,
                'created_by'     => $trainerId,
                'status'         => 'published',
                'published_at'   => now(),
                'approved_at'    => now(),
            ]
        );

        $m1 = $this->mod($course, 1, 'Misingi ya Power BI', 'Power BI Desktop interface, kuunganisha data, na kuunda visuals vya kwanza.');

        $l = $this->lesson($m1, 1, 'Power BI Desktop — Interface na Mwongozo wa Kwanza', 'Jifunza sehemu zote za Power BI Desktop: Report view, Data view, Model view. Unda visual ya kwanza ndani ya dakika 10.', 900,
            [['video_youtube', 'Power BI Desktop Intro — Kuanza Tangu Sifuri', 'https://www.youtube.com/watch?v=TmhQCQr_0aA']],
            '<h2>Power BI Desktop — Chombo cha Kisasa cha Uchambuzi</h2><p>Power BI Desktop ni programu ya bure ya Microsoft kwa Windows inayokuruhusu kuunganisha data, kuifanya mifano, na kuunda ripoti za kisasa ambazo zinaweza kushirikishwa na wengine.</p><h3>Sehemu Tatu Kuu za Power BI Desktop</h3><ul><li><strong>Report View:</strong> Ukurasa unaoonekana na watumiaji — hapa unaweka visuals (charts, tables, cards)</li><li><strong>Data View:</strong> Unaona data yako kama spreadsheet — unaweza kuona na kuhariri calculated columns</li><li><strong>Model View:</strong> Inaonyesha tables zote na uhusiano kati yao (relationships)</li></ul><h3>Hatua za Kwanza</h3><ol><li>Pakua Power BI Desktop kutoka powerbi.microsoft.com (bure)</li><li>Fungua → Get Data → chagua chanzo chako</li><li>Transform Data — safisha katika Power Query</li><li>Close &amp; Apply — rudi Report View</li><li>Buruta field hadi canvas — visual inajijengea yenyewe!</li></ol><blockquote><strong>Tofauti na Excel:</strong> Excel ni nzuri kwa hesabu na data ndogo. Power BI imejengwa kwa ajili ya dashboards za interactive na kushiriki na timu kubwa. Chagua chombo kinachofaa kazi yako.</blockquote>');
        $this->assignment($l, 'Unda Visual ya Kwanza ya Power BI', 'Pakua Power BI Desktop. Pakia dataset ndogo ya mauzo (CSV au Excel). Unda visuals hizi: (1) Card inayoonyesha Jumla ya Mauzo, (2) Bar chart ya mauzo kwa kategoria, (3) Line chart ya mwelekeo wa mauzo kwa mwezi. Format kila visual — ongeza titles na rangi. Chukua screenshot. Kama huna Power BI Desktop, tumia Power BI Service (app.powerbi.com) bure.', 50, 5);

        $l = $this->lesson($m1, 2, 'Kupakia Data na Power Query ndani ya Power BI', 'Power Query ipo ndani ya Power BI pia! Jifunza kuunganisha Excel, CSV, SQL Server. Kusafisha data kabla ya kuunda ripoti.', 1200,
            [['video_youtube', 'Power BI Data Loading na Transformation', 'https://www.youtube.com/watch?v=AGrl-H87pRU']],
            '<h2>Kupakia na Kusafisha Data katika Power BI</h2><p>Power Query ndani ya Power BI inafanya kazi SAWASAWA na Power Query ndani ya Excel. Ujuzi wako wa Power Query unatumika moja kwa moja hapa — hakuna kitu kipya cha kujifunza!</p><h3>Vyanzo vya Data vya Kawaida</h3><ul><li>Excel files (.xlsx, .xls)</li><li>CSV/Text files</li><li>SQL Server, MySQL, PostgreSQL</li><li>SharePoint, OneDrive</li><li>Web pages na REST APIs</li><li>Azure Blob Storage, Google Analytics</li></ul><h3>Power Query ndani ya Power BI</h3><p>Home → Transform Data → Power Query Editor inafunguka. Hapa unafanya mabadiliko yote ya data kama unavyofanya Excel. Ukimaliza: Close &amp; Apply.</p><h3>Incremental Refresh</h3><p>Kwa data kubwa sana (milioni za rows), Power BI ina Incremental Refresh — inasasisha sehemu mpya ya data tu badala ya kuload data yote upya. Inaokoa muda na bandwidth.</p><blockquote><strong>Best Practice:</strong> Fanya usafishaji wote wa data katika Power Query — KABLA ya kujenga ripoti. Kurekebisha data baada ya ripoti imekamilika ni tatizo kubwa. "Garbage in, garbage out."</blockquote>');
        $this->assignment($l, 'Data Model yenye Sources Nyingi', 'Pakia sources mbili katika Power BI: (1) Excel file ya mauzo, (2) CSV file ya bidhaa (au products). Safisha kila moja kwa Power Query — standardize aina za data, ondoa nulls, rename columns. Hakikisha data inapakia vizuri kwenye Model view. Chukua screenshots za Power Query steps. Wasilisha .pbix file.', 60, 7);

        $l = $this->lesson($m1, 3, 'Data Model — Relationships kati ya Tables', 'Star schema vs snowflake schema. Jinsi ya kuunda relationships sahihi kati ya fact tables na dimension tables. Hii ni msingi wa DAX.', 1440,
            [['video_youtube', 'Power BI Data Modeling — Relationships', 'https://www.youtube.com/watch?v=MrLnibFTtbA']],
            '<h2>Data Modeling — Msingi wa Power BI</h2><p>Data Model nzuri ndiyo tofauti kati ya ripoti inayofanya kazi vizuri na moja inayochanganya au kutoa matokeo mabaya. Mfano mbaya wa data = hesabu mbaya = maamuzi mabaya.</p><h3>Star Schema — Muundo Bora</h3><p>Star schema ina:</p><ul><li><strong>Fact Table (Ukweli):</strong> Ina transactions (mauzo, malipo) — rows nyingi, nambari za kuhesabu</li><li><strong>Dimension Tables (Maelezo):</strong> Ina maelezo — Bidhaa, Wateja, Tarehe, Maeneo — rows chache, maelezo</li></ul><h3>Kuunda Relationships</h3><ol><li>Nenda Model View</li><li>Buruta column kutoka Fact table hadi Dimension table (column zinazofanana)</li><li>Power BI inaonyesha mstari wa uhusiano</li><li>Bonyeza-click mstari → Manage Relationship kuona aina</li></ol><h3>Aina za Cardinality</h3><ul><li><strong>Many-to-One (*:1):</strong> Kawaida zaidi — rows nyingi za fact table → row moja ya dimension</li><li><strong>One-to-One (1:1):</strong> Aghali hutumika</li><li><strong>Many-to-Many (*:*):</strong> Epuka ikiwezekana — inaweza kusababisha hesabu zisizo sahihi</li></ul><blockquote><strong>Kanuni ya Muhimu:</strong> Kamwe usiunganishe Fact table na Fact table moja kwa moja. Daima tumia Dimension table kama bridge. Hii inazuia matatizo ya hesabu yanayoitwa "cross filter ambiguity".</blockquote>');
        $this->assignment($l, 'Jenga Star Schema', 'Pewa tables 4 (au ziunda): Sales (Fact), Products (Dim), Customers (Dim), Date (Dim). Katika Power BI Model View: (1) Unda relationships sahihi kati ya Sales na kila Dimension, (2) Angalia cardinality ya kila relationship, (3) Jaribu kuunda card ya Total Sales — inatoa jibu sahihi?, (4) Fanya screenshot ya Data Model yako. Wasilisha .pbix.', 70, 8);

        $l = $this->lesson($m1, 4, 'Basic Visuals — Charts, Tables, Cards', 'Bar chart, line chart, pie chart, table, matrix, card. Jinsi ya kuformat kila visual na kufanya iwe ya kisomi.', 1200,
            [['video_youtube', 'Power BI Visuals — Mwongozo Kamili', 'https://www.youtube.com/watch?v=h5HCpxQsOjU']],
            '<h2>Visuals za Msingi katika Power BI</h2><p>Kila visual katika Power BI ina "wells" (visanduku) unazoweka fields ndani yake — Axis, Values, Legend, n.k. Unabonyeza visual, kisha buruta fields kutoka panel ya data.</p><h3>Visuals za Kawaida na Matumizi Yao</h3><ul><li><strong>Card:</strong> Inaonyesha nambari moja kubwa — Total Sales, Customer Count. Nzuri kwa KPIs</li><li><strong>Bar/Column Chart:</strong> Kulinganisha kategoria. Bar = mlalo, Column = wima</li><li><strong>Line Chart:</strong> Mwelekeo kwa wakati — mauzo kwa miezi</li><li><strong>Pie/Donut Chart:</strong> Sehemu ya jumla — tumia kwa kategoria 5 au chini</li><li><strong>Table:</strong> Data yote — nzuri kwa details</li><li><strong>Matrix:</strong> Kama PivotTable — rows na columns na totals</li><li><strong>Map:</strong> Data ya kijiografia — mauzo kwa mkoa</li></ul><h3>Formatting Visual</h3><p>Chagua visual → Format (brashi icon) → Ubadilishe rangi, fonts, labels, titles, na zaidi. Kila visual ina chaguzi nyingi za formatting.</p><blockquote><strong>Tip ya Design:</strong> Tumia "Format Pane" (Ctrl+E) kufungua formatting yote. Teua "Match report theme" kuhakikisha visuals zote zinatumia rangi sawa. Consistency ndiyo alama ya ripoti ya kitaalamu.</blockquote>');
        $this->assignment($l, 'Dashboard ya Msingi ya Power BI', 'Kutumia data uliyopakia awali, unda ripoti yenye ukurasa 1 na visuals hizi: (1) Card 3 za KPIs, (2) Column chart ya mauzo kwa mwezi, (3) Bar chart ya top 5 bidhaa, (4) Matrix ya mauzo kwa mkoa na mwezi, (5) Pie chart ya sehemu ya mauzo kwa kategoria. Format kila visual — titles, colors, data labels. Wasilisha .pbix.', 80, 10);

        $m2 = $this->mod($course, 2, 'DAX — Lugha ya Power BI', 'DAX (Data Analysis Expressions) — lugha inayotumika kuunda measures na calculated columns.');

        $l = $this->lesson($m2, 1, 'DAX ni Nini? Measures vs Calculated Columns', 'Tofauti muhimu kati ya calculated columns (zinazohifadhiwa) na measures (zinazohesabiwa kwa wakati). Lini kutumia kila moja.', 1200,
            [['video_youtube', 'DAX Basics — Intro kwa Beginners', 'https://www.youtube.com/watch?v=5I-e6xVfDV0']],
            '<h2>DAX — Lugha ya Hesabu katika Power BI</h2><p>DAX (Data Analysis Expressions) ni lugha ya formula inayotumika katika Power BI, Power Pivot, na Analysis Services. Ni kama Excel formulas lakini imeundwa kwa ajili ya data kubwa na mahusiano ya table.</p><h3>Tofauti Kuu: Measures vs Calculated Columns</h3><table border="1" style="border-collapse:collapse; width:100%"><thead><tr><th style="padding:8px">Kipengele</th><th style="padding:8px">Calculated Column</th><th style="padding:8px">Measure</th></tr></thead><tbody><tr><td style="padding:8px">Inahifadhiwa</td><td style="padding:8px">Ndio (katika mfano)</td><td style="padding:8px">Hapana (inehesabiwa papo hapo)</td></tr><tr><td style="padding:8px">Inahesabiwa</td><td style="padding:8px">Mara moja (wakati wa data refresh)</td><td style="padding:8px">Kila visual inapobadilika</td></tr><tr><td style="padding:8px">Context</td><td style="padding:8px">Row context</td><td style="padding:8px">Filter context</td></tr><tr><td style="padding:8px">Matumizi</td><td style="padding:8px">Kuunda column mpya ya kudumu</td><td style="padding:8px">Hesabu za ripoti (SUM, AVG, %)</td></tr></tbody></table><h3>Kuunda Measure</h3><p>Home → New Measure → andika DAX formula:</p><p><code>Total Sales = SUM(Sales[Amount])</code></p><p>Measure inaonekana kwa ikoni ya calculator (∑) katika Fields panel.</p><blockquote><strong>Kanuni:</strong> Kama unahitaji nambari katika visual (SUM, COUNT, AVG), tumia Measure. Kama unahitaji column mpya ya kudumu katika table (kama Profit = Revenue - Cost), tumia Calculated Column.</blockquote>');
        $this->assignment($l, 'Unda Measures za Msingi', 'Katika Power BI model yako ya mauzo, unda measures hizi: (1) Total Revenue = SUM ya mauzo, (2) Total Cost = SUM ya gharama, (3) Gross Profit = Total Revenue - Total Cost, (4) Profit Margin % = DIVIDE(Gross Profit, Total Revenue, 0) formatted kama %, (5) Transaction Count = COUNT ya orders. Onyesha kila measure katika Card visual. Wasilisha .pbix.', 70, 7);

        $l = $this->lesson($m2, 2, 'DAX Functions za Msingi: SUM, COUNT, AVERAGE, CALCULATE', 'CALCULATE ni function muhimu zaidi katika DAX. Jifunza jinsi inavyobadilisha filter context na kufanya calculations ngumu kuwa rahisi.', 1440,
            [['video_youtube', 'CALCULATE Function — Power ya DAX', 'https://www.youtube.com/watch?v=DSv5PCYGZ-E']],
            '<h2>CALCULATE — Function Muhimu Zaidi ya DAX</h2><p>CALCULATE ni function moja lakini yenye nguvu kubwa sana. Inabadilisha "filter context" — yaani, inabadilisha hali ya hesabu bila kubadilisha chochote kwenye ripoti.</p><h3>Muundo wa CALCULATE</h3><p><code>CALCULATE(expression, filter1, filter2, ...)</code></p><h3>Mifano ya Kweli</h3><ul><li><code>Sales 2024 = CALCULATE([Total Sales], YEAR(Sales[Date]) = 2024)</code> — mauzo ya 2024 tu</li><li><code>Sales Dar = CALCULATE([Total Sales], Sales[Region] = "Dar es Salaam")</code> — mauzo ya Dar es Salaam</li><li><code>Sales A+ = CALCULATE([Total Sales], Sales[Category] = "Premium", Sales[Amount] > 1000)</code> — mauzo ya bidhaa za Premium zaidi ya 1000</li></ul><h3>ALL — Ondoa Filters</h3><p><code>ALL([Total Sales]) = CALCULATE([Total Sales], ALL(Sales))</code> — inahesabu jumla yote bila kuzingatia filters za slicer au visual.</p><p>Hii inatumika kwa % ya jumla: <code>% of Total = DIVIDE([Total Sales], CALCULATE([Total Sales], ALL(Sales)))</code></p><blockquote><strong>Kuelewa CALCULATE:</strong> Fikiria CALCULATE kama "scope" ya hesabu. Bila CALCULATE, measure inazingatia filters zote za ripoti. CALCULATE inakuruhusu kubadilisha scope hiyo — hata kufuta filters fulani au kuongeza filters mpya.</blockquote>');
        $this->assignment($l, 'DAX Measures za Biashara kwa CALCULATE', 'Katika model yako ya mauzo, unda measures hizi kwa CALCULATE: (1) Sales Previous Month = mauzo ya mwezi uliopita, (2) Sales YTD = mauzo ya mwaka hadi sasa, (3) % Contribution = sehemu ya kila kategoria kwa jumla, (4) Sales Target vs Actual = linganisha na lengo lililowekwa kwenye table nyingine. Onyesha kila measure katika visual. Wasilisha .pbix.', 100, 10);

        $l = $this->lesson($m2, 3, 'Time Intelligence: Year-to-Date, Month-over-Month', 'DAX time functions — TOTALYTD, DATEADD, SAMEPERIODLASTYEAR. Kulinganisha mauzo ya mwaka huu na mwaka uliopita kwa ease.', 1440,
            [['video_youtube', 'Time Intelligence DAX Functions', 'https://www.youtube.com/watch?v=E8D4SVUTJGU']],
            '<h2>Time Intelligence — Hesabu za Wakati katika DAX</h2><p>Time Intelligence functions ni kundi la functions za DAX zinazofanya iwe rahisi kulinganisha data kwa wakati — mwaka huu vs mwaka uliopita, mwezi huu vs mwezi uliopita, na zaidi.</p><h3>Sharti Muhimu: Date Table</h3><p>Time Intelligence inafanya kazi vizuri TU ukiwa na Date table iliyoundwa vizuri katika mfano wako. Unda Date table au tumia DAX:</p><p><code>DateTable = CALENDAR(DATE(2020,1,1), DATE(2026,12,31))</code></p><h3>Functions za Kawaida za Time Intelligence</h3><ul><li><code>TOTALYTD([Sales], DateTable[Date])</code> — Jumla ya mwaka hadi leo</li><li><code>TOTALMTD([Sales], DateTable[Date])</code> — Jumla ya mwezi hadi leo</li><li><code>SAMEPERIODLASTYEAR(DateTable[Date])</code> — Kipindi sawa mwaka uliopita</li><li><code>DATEADD(DateTable[Date], -1, MONTH)</code> — Mwezi uliopita</li><li><code>PREVIOUSMONTH(DateTable[Date])</code> — Mwezi uliopita (njia rahisi zaidi)</li></ul><h3>Growth % Formula</h3><p><code>YoY Growth % = DIVIDE([Sales] - [Sales LY], [Sales LY], 0)</code></p><p>Inaonyesha ukuaji wa asilimia kutoka mwaka uliopita. Ukuaji chanya = nzuri, hasi = kuanguka.</p><blockquote><strong>Tip:</strong> Weka DateTable yako kama "Mark as Date Table" (Table Tools → Mark as Date Table) ili Power BI ijue ni Date table. Hii inafanya Time Intelligence functions zifanye kazi vizuri zaidi.</blockquote>');
        $this->assignment($l, 'Ripoti ya Mwelekeo wa Mauzo (Time Intelligence)', 'Katika Power BI ripoti yako, unda: (1) Measure ya Sales LY (Last Year), (2) Measure ya YoY Growth %, (3) Measure ya Sales YTD, (4) Line chart inayoonyesha Sales vs Sales LY kwa kila mwezi wa 2024, (5) Card inayoonyesha YoY Growth % (kijani kama chanya, nyekundu kama hasi). Thibitisha hesabu kwa Excel kwa mkono. Wasilisha .pbix.', 90, 10);

        $l = $this->lesson($m2, 4, 'Filter Context na Row Context', 'Dhana muhimu sana katika DAX ambayo wengi hawaielewe vizuri. Kuelewa hii kutakufanya mtaalamu wa DAX.', 1200,
            [['video_youtube', 'Filter Context na Row Context — Kwa Undani', 'https://www.youtube.com/watch?v=q1FBBZ0acag']],
            '<h2>Filter Context na Row Context — Siri ya DAX</h2><p>Hizi ni dhana ngumu lakini muhimu zaidi katika DAX. Ukizielewa vizuri, utaweza kutatua matatizo yoyote ya DAX.</p><h3>Row Context</h3><p>Row Context inatokea wakati DAX inazunguka rows moja moja — kama loop. Hii inatokea katika: Calculated Columns, na ndani ya functions za iterator (SUMX, AVERAGEX, MAXX, n.k.).</p><p><code>Profit = Sales[Revenue] - Sales[Cost]</code> — hii ni row context, inafanya kwa kila row.</p><h3>Filter Context</h3><p>Filter Context ni "mazingira ya hesabu" ya measure. Inabadilika kulingana na: (1) Filters za slicer, (2) Axis ya chart, (3) Rows/Columns za matrix, (4) Filters za CALCULATE.</p><h3>Iterator Functions (Row Context Manual)</h3><p>Functions zinazomalizia kwa X — SUMX, AVERAGEX, MINX, MAXX — zinazunguka rows moja moja na kuhesabu kitu kwa kila row, kisha kufanya aggregation.</p><p><code>Total Revenue = SUMX(Sales, Sales[Qty] * Sales[Price])</code> — inazidisha Qty na Price kwa kila row, kisha kufanya SUM.</p><blockquote><strong>Kanuni ya Mkono wa Kulia:</strong> Ukiandika DAX na hujui tatizo ni nini, jiulize: "Hii measure inafanya kazi katika filter context gani sasa hivi?" Jibu hilo linakusaidia kuelewa kwa nini unapata matokeo yasiyotarajiwa.</blockquote>');
        $this->assignment($l, 'Filter na Row Context kwa Vitendo', 'Katika Power BI, unda scenario hizi na ueleze kwa maandishi kwa nini hesabu inafanya kazi hivyo: (1) Measure inayotoa matokeo tofauti katika card vs katika matrix row, (2) Calculated column ya Profit vs Measure ya Total Profit — tofauti yao, (3) SUMX formula inayozidisha bei na idadi (row context), (4) CALCULATE inayobadilisha filter context. Wasilisha .pbix + maelezo ya kila mfano.', 100, 12);

        $m3 = $this->mod($course, 3, 'Dashboard ya Kitaalamu na Kushiriki', 'Unda dashboards nzuri na uzishirikishe na timu kupitia Power BI Service.');

        $l = $this->lesson($m3, 1, 'Report Design — Layout, Colors, na Branding', 'Kanuni za design ya professional report: white space, consistent colors, font sizes, alignment. Templates na themes.', 1080,
            [['video_youtube', 'Power BI Report Design Best Practices', 'https://www.youtube.com/watch?v=c7LrqSxjJQQ']],
            '<h2>Report Design — Jinsi ya Kuunda Ripoti ya Kupendeza na Inayoeleweka</h2><p>Ripoti nzuri si tu hesabu sahihi — lazima iwe rahisi kusoma, ya kupendeza, na inayoelekeza macho ya msomaji mahali pazuri.</p><h3>Kanuni 5 za Design Nzuri</h3><ol><li><strong>Hierarchy ya Habari:</strong> Habari muhimu zaidi iwe kubwa na juu — KPI cards kwanza, details chini</li><li><strong>Consistency:</strong> Rangi, fonts, na ukubwa wa visuals viwe sawa katika ripoti nzima</li><li><strong>White Space:</strong> Usijaze kila sehemu — pumzika inasaidia macho na uelewa</li><li><strong>Color na Meaning:</strong> Kijani = nzuri, nyekundu = mbaya. Tumia rangi kuwasilisha maana</li><li><strong>Simplicity:</strong> Kila visual iwe na lengo moja. Ukiongeza visual, jiulize: "Inasaidia maamuzi gani?"</li></ol><h3>Themes katika Power BI</h3><p>View → Themes — chagua theme iliyoundwa mapema au ingiza JSON ya theme yako. Themes zinabadilisha rangi, fonts, na muundo wa visuals zote mara moja.</p><h3>Backgrounds na Shapes</h3><p>Insert → Shapes au Background Images — unaweza kuongeza backgrounds za kibiashara au alama ya kampuni (logo).</p><blockquote><strong>Mfano Mbaya:</strong> Charts 8 kwenye ukurasa mmoja, rangi 12 tofauti, fonts 4 tofauti, na hakuna hierarchy ya habari — hii ni "chart junk". Chini ni zaidi zaidi.</blockquote>');
        $this->assignment($l, 'Redesign ya Ripoti Isiyopendeza', 'Pewa (au unda) ripoti mbaya ya Power BI — charts nyingi sana, rangi zisizopendeza, hakuna hierarchy. Ifanye upya kwa kanuni za design: (1) Weka KPI cards 3 juu, (2) Punguza visuals hadi 4 muhimu tu, (3) Tumia theme moja ya kampuni (rangi 2-3 tu), (4) Ongeza white space, (5) Weka titles na maelezo mafupi kwa kila visual. Wasilisha: kabla na baada. .pbix.', 70, 8);

        $l = $this->lesson($m3, 2, 'Slicers, Filters, na Drill-through', 'Kufanya ripoti yako interactive — slicers za tarehe, dropdowns, cross-filtering kati ya visuals. Drill-through kwa undani wa data.', 1200,
            [['video_youtube', 'Slicers na Filters katika Power BI', 'https://www.youtube.com/watch?v=7-2VePPcFvY']],
            '<h2>Slicers, Filters, na Drill-through — Ripoti ya Interactive</h2><p>Nguvu ya Power BI kuliko Excel ni interactivity — mtumiaji anaweza kuchunguza data mwenyewe bila msaada wa mtu. Slicers na filters ndizo zana kuu za interactivity.</p><h3>Slicers</h3><p>Slicers ni vifungo vya kuchuja — mtumiaji anabonyeza na ripoti inabadilika moja kwa moja. Unda slicer: Insert → Slicer → chagua field (mfano: Mwaka, Mkoa).</p><h3>Aina za Slicers</h3><ul><li><strong>List Slicer:</strong> Orodha ya vifungo — vizuri kwa items chache</li><li><strong>Dropdown Slicer:</strong> Orodha ya kushuka — vizuri kwa items nyingi</li><li><strong>Date Range Slicer:</strong> Uchaguzi wa tarehe na between/before/after</li><li><strong>Slider Slicer:</strong> Slider ya nambari — vizuri kwa range ya bei</li></ul><h3>Cross-filtering</h3><p>Ukibonyeza bar moja ya chart, visuals zingine zinachujwa moja kwa moja. Hii inaitwa cross-filtering na ni nzuri sana kwa kuchunguza data. Unaweza kusetupia jinsi cross-filtering inavyofanya kazi: Format → Edit Interactions.</p><h3>Drill-through</h3><p>Unda ukurasa wa "details" — mtumiaji anabonyeza-kulia kwenye bidhaa katika chart → Drill through → anaona page ya details ya bidhaa hiyo. Nguvu sana kwa executive summaries na details za ndani.</p><blockquote><strong>Tip:</strong> Weka Sync Slicers ukitaka slicer ifanye kazi kwenye kurasa nyingi. View → Sync Slicers → chagua ukurasa gani slicer itaathiri.</blockquote>');
        $this->assignment($l, 'Ripoti yenye Interactivity Kamili', 'Unda Power BI ripoti yenye kurasa 2: (1) Summary page yenye slicers za Mwaka na Mkoa, charts 3 zinazochuja kwa pamoja, na KPI cards. (2) Detail page yenye drill-through kutoka bidhaa katika summary chart — inaonyesha details za bidhaa hiyo (mauzo kwa mwezi, wateja wakuu, mwelekeo). Jaribu: bonyeza bidhaa moja → drill-through inafungua detail page. Wasilisha .pbix.', 90, 10);

        $l = $this->lesson($m3, 3, 'Kuchapisha kwenye Power BI Service na Kushiriki', 'Publish report kwenye Power BI Service. Kuunda dashboards, kusetupia data refresh, na kushiriki na timu. Row-level security.', 1080,
            [['video_youtube', 'Power BI Service — Kushiriki Ripoti', 'https://www.youtube.com/watch?v=gqO0zx3qv3g']],
            '<h2>Power BI Service — Kushiriki Ripoti na Timu</h2><p>Power BI Desktop ni kwa kuunda ripoti. Power BI Service (app.powerbi.com) ni kwa kushiriki na timu, kusetupia refresh, na kuunda dashboards za pinned visuals.</p><h3>Hatua za Kuchapisha</h3><ol><li>Power BI Desktop → Home → Publish</li><li>Chagua Workspace katika Power BI Service</li><li>Fungua Power BI Service — ripoti yako ipo!</li></ol><h3>Workspaces</h3><p>Workspace ni folda ya pamoja kwa timu. Watu wote wa timu wanaweza kuona na kuhariri reports katika workspace moja. Unda Workspace: New Workspace → waalika wenzako.</p><h3>Scheduled Data Refresh</h3><p>Dataset → Settings → Scheduled Refresh — setupia data isasishwe moja kwa moja kila siku, wiki, au saa.</p><h3>Row-Level Security (RLS)</h3><p>Unaweza kudhibiti ni data gani kila mtu anaona. Mfano: Meneja wa Dar es Salaam anaona tu data ya Dar, Meneja wa Mwanza anaona ya Mwanza tu — ripoti ni moja!</p><blockquote><strong>Kumbuka:</strong> Power BI Service ina toleo la bure (Power BI Free) na toleo la kulipa (Power BI Pro). Kushiriki ripoti na wengine kunahitaji Power BI Pro au Premium. Kampuni nyingi zina Microsoft 365 Business ambayo inajumuisha Power BI Pro.</blockquote>');
        $this->assignment($l, 'Chapisha na Shiriki Ripoti', 'Chapisha ripoti yako ya Power BI kwenye Power BI Service (unda akaunti ya bure kama huna). Fanya yafuatayo: (1) Publish ripoti yako, (2) Unda Dashboard kwa kupachika visuals muhimu, (3) Setupia Data Refresh (hata kwa manual refresh), (4) Shiriki dashboard na mtu mmoja (mwanafunzi mwenzako au mwalimu), (5) Angalia ripoti kwenye simu ya mkononi kwa Power BI Mobile app. Wasilisha screenshots za kila hatua.', 80, 10);

        $l = $this->lesson($m3, 4, 'Mradi wa Mwisho: Executive Dashboard', 'Unganisha maarifa yote — unda executive dashboard kamili inayoonyesha KPIs za biashara: mauzo, faida, wateja, na mwelekeo.', 3600,
            [['video_youtube', 'Power BI Executive Dashboard — Mradi Kamili', 'https://www.youtube.com/watch?v=8QXXrz14OUc']],
            '<h2>Executive Dashboard — Mradi wa Mwisho</h2><p>Unaunganisha kila kitu ulichojifunza katika kozi hii. Unda dashboard inayofaa kwa CEO au CFO wa kampuni — inawasilisha hali ya biashara katika sekunde 30.</p><h3>Muundo wa Executive Dashboard Bora</h3><ul><li><strong>Ukurasa 1 — Overview:</strong> KPI cards 4-6 (Revenue, Profit, Growth, Customers), Trend line, Regional map</li><li><strong>Ukurasa 2 — Sales Detail:</strong> PivotTable ya mauzo kwa bidhaa/mkoa/mwezi, drill-through</li><li><strong>Ukurasa 3 — Financial:</strong> P&amp;L summary, margin trends, cost breakdown</li></ul><h3>DAX Measures za Executive</h3><ul><li>Revenue, Gross Profit, Net Profit</li><li>YoY Growth % kwa kila KPI</li><li>Budget vs Actual variance</li><li>Rolling 12-month average</li></ul><h3>Vipengele vya Lazima</h3><ol><li>Slicers za mwaka na mkoa (synced katika kurasa zote)</li><li>Conditional formatting (nyekundu/kijani) kwa growth</li><li>Drill-through kutoka overview hadi details</li><li>Mobile-friendly layout (tablet view)</li><li>Scheduled refresh katika Power BI Service</li></ol><blockquote><strong>Kipimo cha Mafanikio:</strong> Mpe CEO wako dashboard yako na aone kwa dakika 2 bila msaada wako. Akielewa hali ya biashara na data, umefanikiwa. Kama anahitaji maelezo yako ya kila hatua — ibunifu upya.</blockquote>');
        $this->assignment($l, 'Executive Sales Dashboard', 'Unda Power BI dashboard kamili kwa data ya mauzo ya miaka 3. Lazima iwe na: (1) KPI cards — Revenue, Profit, Customers, Growth %, (2) Trend chart ya kila mwezi (na LY comparison), (3) Top 10 products kwa bar chart, (4) Regional breakdown kwa map na table, (5) Year-over-year comparison kwa matrix, (6) Slicers za mwaka, mkoa, na kategoria, (7) Drill-through page ya details za bidhaa. Chapisha kwenye Power BI Service. Wasilisha .pbix + link ya Service + screenshots.', 120, 21);
    }

    // =========================================================================
    // COURSE 4 — Financial Accounting & IFRS
    // =========================================================================
    private function accountingCourse(int $trainerId): void
    {
        $course = Course::updateOrCreate(
            ['title' => 'Uhasibu wa Fedha na Viwango vya IFRS'],
            [
                'description'    => 'Jifunza misingi ya uhasibu — double entry, financial statements, na viwango vya kimataifa vya IFRS. Kozi hii inafaa kwa wanaohesabu, managers wa fedha, na wajasiriamali wanaotaka kuelewa fedha za kampuni yao.',
                'category'       => 'accounting',
                'level'          => 'beginner',
                'duration_hours' => 22,
                'price_tzs'      => 0,
                'instructor_id'  => $trainerId,
                'created_by'     => $trainerId,
                'status'         => 'published',
                'published_at'   => now(),
                'approved_at'    => now(),
            ]
        );

        $m1 = $this->mod($course, 1, 'Misingi ya Uhasibu (Accounting Fundamentals)', 'Kanuni za msingi za uhasibu, mfumo wa double-entry, na aina za akaunti.');

        $l = $this->lesson($m1, 1, 'Uhasibu ni Nini na Kwa Nini ni Muhimu?', 'Maana ya uhasibu, tofauti kati ya bookkeeping na accounting, na umuhimu wake katika biashara yoyote kubwa au ndogo.', 900,
            [['video_youtube', 'Intro ya Uhasibu kwa Beginners', 'https://www.youtube.com/watch?v=yYX4bvQSqbo']],
            '<h2>Uhasibu — Lugha ya Biashara</h2><p>Uhasibu ni sanaa na sayansi ya kurekodi, kuainisha, na kufupisha matukio ya kifedha ya biashara ili kutoa habari muhimu kwa waamuzi.</p><h3>Tofauti kati ya Bookkeeping na Accounting</h3><ul><li><strong>Bookkeeping:</strong> Kurekodi miamala ya kila siku — kuandika receipts, kuingiza data, kulipa bili. Ni kazi ya kiufundi.</li><li><strong>Accounting:</strong> Kuchanganua, kutafsiri, na kuripoti data ya fedha. Ni kazi inayohitaji hukumu na ujuzi wa juu.</li></ul><h3>Kwa Nini Uhasibu ni Muhimu?</h3><ul><li><strong>Maamuzi ya Biashara:</strong> Je, tunapata faida? Je, tunaweza kukopa? Je, tununue mali mpya?</li><li><strong>Kodi na Sheria:</strong> TRA inahitaji taarifa za fedha kwa ajili ya kodi. Kukosa kumbukumbu = tatizo kubwa la kisheria</li><li><strong>Wawekezaji na Benki:</strong> Hawatawekeza au kukopa bila kuona taarifa za fedha za uwazi</li><li><strong>Udhibiti wa Ndani:</strong> Kuzuia wizi na ubadhirifu wa mali za kampuni</li></ul><h3>Mzunguko wa Uhasibu</h3><p>Muamala → Journal Entry → Ledger → Trial Balance → Financial Statements → Analysis</p><blockquote><strong>Ukweli:</strong> Kampuni nyingi ndogo zinaanguka si kwa sababu hazina mauzo, bali kwa sababu hazijui hali yao ya fedha. Uhasibu mzuri = biashara inayodumu.</blockquote>');
        $this->assignment($l, 'Tathmini ya Hali ya Biashara Ndogo', 'Chagua biashara ndogo unayoijua (duka la karibu, salon, restaurant). Fanya tathmini: (1) Orodhesha vitu 5 vya mali (assets) wanazovimiliki, (2) Orodhesha madeni 3 (liabilities) wanayodaiwa, (3) Hesabu "net worth" = assets - liabilities, (4) Andika kwa nini biashara hiyo inahitaji kuhifadhi kumbukumbu za fedha, (5) Je, unafikiria biashara hiyo ina faida au hasara? Wasilisha ripoti fupi (.docx)', 40, 5);

        $l = $this->lesson($m1, 2, 'Double Entry System — Mfumo wa Ingizo Mbili', 'Kila muamala wa biashara una pande mbili — debit na credit. Jifunza kanuni hii muhimu zaidi ya uhasibu na jinsi inavyofanya kazi.', 1440,
            [['video_youtube', 'Double Entry Accounting Explained', 'https://www.youtube.com/watch?v=2aaHEH7gjXw']],
            '<h2>Double Entry System — Kanuni ya Msingi ya Uhasibu</h2><p>Mfumo wa ingizo mbili unasema: <strong>kila muamala wa fedha una athari mbili — upande wa debit na upande wa credit</strong>. Ndiyo maana inaitwa "double entry" — unarekodi mara mbili.</p><h3>Kanuni ya Msingi</h3><p style="text-align:center"><strong>Debit = Credit daima</strong></p><p>Hii inaitwа accounting equation equilibrium. Ukiangalia hesabu yako na debit ≠ credit — kuna kosa mahali.</p><h3>Debit vs Credit kwa Aina za Akaunti</h3><table border="1" style="border-collapse:collapse; width:100%"><thead><tr><th style="padding:8px">Aina ya Akaunti</th><th style="padding:8px">Inaongezeka kwa</th><th style="padding:8px">Inapungua kwa</th></tr></thead><tbody><tr><td style="padding:8px">Assets (Mali)</td><td style="padding:8px">Debit</td><td style="padding:8px">Credit</td></tr><tr><td style="padding:8px">Liabilities (Madeni)</td><td style="padding:8px">Credit</td><td style="padding:8px">Debit</td></tr><tr><td style="padding:8px">Equity (Hisa)</td><td style="padding:8px">Credit</td><td style="padding:8px">Debit</td></tr><tr><td style="padding:8px">Revenue (Mapato)</td><td style="padding:8px">Credit</td><td style="padding:8px">Debit</td></tr><tr><td style="padding:8px">Expenses (Gharama)</td><td style="padding:8px">Debit</td><td style="padding:8px">Credit</td></tr></tbody></table><h3>Mfano wa Vitendo</h3><p>Mnunuzi alinunua bidhaa kwa TZS 500,000 kwa pesa taslimu:</p><ul><li>Dr Cash (Mali inapungua) TZS 500,000 — wait, inaongezeka! Dr Mali = Dr</li><li>Cr Inventory (Mali inapungua) TZS 500,000</li></ul><blockquote><strong>Kumbuka kwa Urahisi:</strong> DEAD CLIC — Debits increase Expenses, Assets, Drawings. Credits increase Liabilities, Income, Capital.</blockquote>');
        $this->assignment($l, 'Muamala kwa Double Entry', 'Kampuni ilifanya miamala hii wiki moja: (1) Mwenye biashara alileta mtaji TZS 3,000,000, (2) Walinunua bidhaa kwa TZS 1,200,000 kwa mkopo, (3) Waliuza bidhaa kwa TZS 800,000 kwa pesa, (4) Walilipa kodi TZS 150,000, (5) Walilipa deni la ununuzi wa bidhaa TZS 600,000. Kwa kila muamala: andika upande wa Debit na Credit. Hakikisha Debit = Credit kwa kila muamala. Wasilisha Excel au PDF.', 60, 7);

        $l = $this->lesson($m1, 3, 'Aina za Akaunti: Assets, Liabilities, Equity', 'Jifunza accounting equation: Assets = Liabilities + Equity. Aina za akaunti na jinsi zinavyoathiriana.', 1200,
            [['video_youtube', 'Accounting Equation na Account Types', 'https://www.youtube.com/watch?v=hj7nJCLCHoI']],
            '<h2>Aina za Akaunti na Accounting Equation</h2><p>Kila akaunti katika uhasibu ipo katika moja ya makundi matano. Kuelewa makundi haya ni msingi wa kuelewa financial statements zote.</p><h3>Accounting Equation</h3><p style="text-align:center; font-size:1.2em"><strong>Assets = Liabilities + Equity</strong></p><p>Equation hii lazima iwe sawasawa (balanced) wakati wote. Hii ndiyo siri ya uhasibu.</p><h3>Makundi Matano ya Akaunti</h3><ul><li><strong>1. Assets (Mali):</strong> Kila kitu kampuni inachomiliki — Pesa (Cash), Bidhaa (Inventory), Majengo, Magari, Madeni yanayodaiwa (Accounts Receivable)</li><li><strong>2. Liabilities (Madeni):</strong> Kila kitu kampuni inadaiwa — Mikopo ya benki, bili zisizolipwa (Accounts Payable), mishahara inayodaiwa</li><li><strong>3. Equity (Hisa ya Wamiliki):</strong> Tofauti kati ya assets na liabilities — ndiyo "thamani halisi" ya kampuni kwa wamiliki</li><li><strong>4. Revenue (Mapato):</strong> Pesa inayoingia kutoka biashara ya kawaida — mauzo ya bidhaa, ada za huduma</li><li><strong>5. Expenses (Gharama):</strong> Gharama za kuendesha biashara — mishahara, kodi, umeme, transport</li></ul><h3>Chart of Accounts</h3><p>Chart of Accounts ni orodha ya akaunti zote za kampuni na nambari zao. Kila kampuni inaunda yake. Mfano wa Tanzania:<br>1xxx = Assets, 2xxx = Liabilities, 3xxx = Equity, 4xxx = Revenue, 5xxx = Expenses</p><blockquote><strong>Ukweli Muhimu:</strong> Revenue na Expenses ni sehemu ya Equity (zinaingia Retained Earnings mwisho wa mwaka). Kwa hiyo equation kamili ni: Assets = Liabilities + Capital + Revenue - Expenses.</blockquote>');
        $this->assignment($l, 'Jenga Chart of Accounts ya Biashara', 'Fikiria biashara ya mgahawa mdogo wa Tanzania. Unda Chart of Accounts yenye angalau akaunti 20: (1) Assets 6 (pesa, bidhaa, vifaa, n.k.), (2) Liabilities 4 (mikopo, bili, n.k.), (3) Equity 2, (4) Revenue 3 (mauzo chakula, vinywaji, catering), (5) Expenses 5+ (mishahara, kodi, umeme, bidhaa, n.k.). Kila akaunti iwe na nambari na jina. Wasilisha Excel au PDF.', 50, 6);

        $l = $this->lesson($m1, 4, 'Journal Entries — Kuandika Muamala', 'Jinsi ya kuandika journal entries sahihi kwa muamala wa kawaida: mauzo, ununuzi, malipo ya mshahara, depreciation.', 1440,
            [['video_youtube', 'Journal Entries — Mifano ya Kweli', 'https://www.youtube.com/watch?v=YM9lj5pMuNw']],
            '<h2>Journal Entries — Jinsi ya Kurekodi Miamala</h2><p>Journal ni kitabu cha kwanza cha kurekodi miamala. Kila muamala unaandikwa katika journal kabla ya kuhifadhiwa katika ledger (vitabu vya akaunti binafsi).</p><h3>Muundo wa Journal Entry</h3><pre>Tarehe | Akaunti | Dr | Cr\n------|---------|-------|------\n2024-01-15 | Cash | 500,000 |\n           | Sales Revenue |  | 500,000\n (Sold goods for cash)</pre><h3>Miamala ya Kawaida na Journal Entries Zake</h3><ul><li><strong>Mauzo kwa pesa:</strong> Dr Cash / Cr Sales Revenue</li><li><strong>Mauzo kwa mkopo:</strong> Dr Accounts Receivable / Cr Sales Revenue</li><li><strong>Ununuzi wa bidhaa kwa pesa:</strong> Dr Inventory / Cr Cash</li><li><strong>Ununuzi wa bidhaa kwa mkopo:</strong> Dr Inventory / Cr Accounts Payable</li><li><strong>Kulipa mishahara:</strong> Dr Salaries Expense / Cr Cash</li><li><strong>Kulipa kodi:</strong> Dr Rent Expense / Cr Cash</li><li><strong>Kulipa deni:</strong> Dr Accounts Payable / Cr Cash</li><li><strong>Depreciation:</strong> Dr Depreciation Expense / Cr Accumulated Depreciation</li></ul><h3>General Ledger (T-Accounts)</h3><p>Baada ya journal entries, kila akaunti inahamishiwa kwenye ledger yake (T-account). T-account inaonyesha debits upande wa kushoto na credits upande wa kulia, na balance mwishoni.</p><blockquote><strong>Mfumo wa Kufanya Kazi:</strong> (1) Tambua miamala, (2) Andika journal entries, (3) Post kwenye T-accounts, (4) Hesabu balances, (5) Tengeneza Trial Balance. Hii ni mzunguko wa msingi wa uhasibu.</blockquote>');
        $this->assignment($l, 'Journal Entries za Kampuni Mpya', 'Kampuni mpya ya biashara ilifanya miamala hii katika Januari 2024: (1) 01-Jan: Mwenye biashara aliweka mtaji TZS 5,000,000 banki, (2) 05-Jan: Walinunua bidhaa TZS 2,000,000 kwa pesa, (3) 10-Jan: Waliuza bidhaa TZS 1,500,000 kwa pesa, (4) 15-Jan: Walilipa kodi TZS 300,000, (5) 20-Jan: Walinunua kompyuta TZS 800,000 kwa mkopo, (6) 25-Jan: Walipokea ada ya ushauri TZS 400,000 mkopo. Andika journal entries zote. Onyesha T-accounts za Cash, Inventory, Sales Revenue. Wasilisha Excel au PDF.', 80, 10);

        $m2 = $this->mod($course, 2, 'Ripoti za Fedha (Financial Statements)', 'Taarifa ya Mapato, Mizania, na Taarifa ya Mtiririko wa Pesa — jinsi ya kuziandaa na kuzisoma.');

        $l = $this->lesson($m2, 1, 'Income Statement — Taarifa ya Mapato', 'Jinsi ya kuandaa Income Statement. Revenue, Cost of Goods Sold, Gross Profit, Operating Expenses, Net Profit. Mfano kamili.', 1440,
            [['video_youtube', 'Income Statement — Jinsi ya Kuandaa', 'https://www.youtube.com/watch?v=WEDIj9JBTC8']],
            '<h2>Income Statement — Taarifa ya Mapato na Matumizi</h2><p>Income Statement (P&amp;L — Profit and Loss) inaonyesha kama kampuni ilifanya faida au hasara katika kipindi fulani (mwezi, robo mwaka, mwaka). Inachunguza mapato dhidi ya gharama.</p><h3>Muundo wa Income Statement</h3><pre>KAMPUNI XYZ — TAARIFA YA MAPATO\nKwa Mwaka Ulioisha 31 Desemba 2024\n\nMapato ya Mauzo (Revenue)          10,000,000\nGharama ya Bidhaa Zilizouzwa (COGS) (6,000,000)\n──────────────────────────────────\nFaida ya Jumla (Gross Profit)        4,000,000\n\nGharama za Uendeshaji:\n  Mishahara                 (1,200,000)\n  Kodi                        (300,000)\n  Umeme &amp; Maji               (100,000)\n  Matangazo                  (200,000)\n──────────────────────────────────\nFaida Kabla ya Kodi (EBIT)          2,200,000\nRiba ya Mkopo                        (200,000)\nFaida Kabla ya Kodi (EBT)           2,000,000\nKodi ya Mapato (30%)                 (600,000)\n──────────────────────────────────\nFaida Baada ya Kodi (Net Income)    1,400,000</pre><h3>Metrics Muhimu</h3><ul><li><strong>Gross Profit Margin:</strong> Gross Profit ÷ Revenue × 100 = 40% (mfano)</li><li><strong>Net Profit Margin:</strong> Net Income ÷ Revenue × 100 = 14%</li><li><strong>EBITDA:</strong> Earnings Before Interest, Tax, Depreciation, Amortization — inatumika kwa ulinganisho</li></ul><blockquote><strong>Tofauti Muhimu:</strong> Revenue ni pesa inayodaiwa (au kupokelewa) kwa bidhaa/huduma. Profit ni kilichobaki baada ya kutoa gharama zote. Kampuni inaweza kuwa na Revenue kubwa lakini bado iwe na hasara kama gharama ni kubwa zaidi.</blockquote>');
        $this->assignment($l, 'Andaa Income Statement', 'Kutoka kwa data hii ya trial balance ya kampuni ya duka la electronics, andaa Income Statement kamili kwa mwaka 2024: Revenue TZS 15M, COGS TZS 9M, Mishahara TZS 2.4M, Kodi TZS 600K, Umeme TZS 300K, Matangazo TZS 500K, Depreciation TZS 200K, Riba ya Mkopo TZS 150K, Kodi ya Mapato 30%. Hesabu: Gross Profit, EBIT, EBT, Net Income, Gross Margin %, Net Margin %. Wasilisha Excel au PDF.', 80, 10);

        $l = $this->lesson($m2, 2, 'Balance Sheet — Mizania ya Kampuni', 'Mizania inaonyesha hali ya fedha ya kampuni siku fulani. Assets, Liabilities, Shareholders Equity. Jinsi ya kusoma na kuchambua.', 1440,
            [['video_youtube', 'Balance Sheet Explained', 'https://www.youtube.com/watch?v=e19nC9y7HBo']],
            '<h2>Balance Sheet — Picha ya Hali ya Fedha</h2><p>Balance Sheet (Mizania) ni picha ya hali ya fedha ya kampuni katika siku moja maalum — si kipindi, bali siku moja. Inasema: "Leo, hali ya fedha yetu ni hivi."</p><h3>Muundo wa Balance Sheet</h3><pre>KAMPUNI XYZ — MIZANIA\nKufikia 31 Desemba 2024\n\nMALI (ASSETS)\n  Mali ya Muda Mfupi (Current Assets):\n    Pesa Taslimu (Cash)         2,000,000\n    Madeni yanayodaiwa (AR)      800,000\n    Bidhaa (Inventory)         1,200,000\n  Jumla ya Mali ya Muda Mfupi  4,000,000\n\n  Mali ya Muda Mrefu (Non-Current):\n    Majengo na Ardhi           5,000,000\n    Vifaa na Mitambo           2,000,000\n    Minus: Mkustanyiko (AccDep) (500,000)\n  Jumla ya Mali ya Muda Mrefu  6,500,000\n\nJUMLA YA MALI                  10,500,000\n════════════════════════════════\nMADENI (LIABILITIES)\n  Muda Mfupi (Current):\n    Accounts Payable             600,000\n    Mkopo wa Benki               400,000\n  Muda Mrefu: Mkopo wa Muda Mrefu 2,000,000\nJUMLA YA MADENI                3,000,000\n\nHISA YA WAMILIKI (EQUITY)\n  Mtaji                        6,100,000\n  Faida Zilizohifadhiwa        1,400,000\nJUMLA YA HISA                  7,500,000\n\nJUMLA MADENI + HISA            10,500,000</pre><blockquote><strong>Muhimu:</strong> Jumla ya Assets lazima iwe SAWASAWA na Jumla ya Liabilities + Equity. Hii ndiyo inayomaanisha "mizania" — imepimia.</blockquote>');
        $this->assignment($l, 'Tengeneza Balance Sheet', 'Kutoka journal entries za Januari 2024 (kazi ya awali), unda Balance Sheet kufikia 31 Januari 2024. Hesabu balances za kila akaunti kutoka T-accounts. Onyesha: Current Assets, Non-current Assets, Current Liabilities, Long-term Liabilities, na Equity. Thibitisha: Assets = Liabilities + Equity. Wasilisha Excel au PDF.', 90, 12);

        $l = $this->lesson($m2, 3, 'Cash Flow Statement — Taarifa ya Mtiririko wa Pesa', 'Tofauti kati ya profit na cash. Direct vs indirect method. Operating, investing, na financing activities.', 1440,
            [['video_youtube', 'Cash Flow Statement', 'https://www.youtube.com/watch?v=sI6xMNyFMPo']],
            '<h2>Cash Flow Statement — Harakati za Pesa Taslimu</h2><p>Cash Flow Statement inaonyesha pesa halisi iliyoingia na kutoka. Kampuni inaweza kuwa na <strong>faida kubwa lakini haina pesa taslimu</strong> — hii ni tatizo la kawaida!</p><h3>Sehemu Tatu za Cash Flow</h3><ul><li><strong>Operating Activities:</strong> Pesa kutoka shughuli za kawaida za biashara — mauzo, malipo kwa wasambazaji, mishahara. Hii ndiyo sehemu muhimu zaidi.</li><li><strong>Investing Activities:</strong> Pesa kutoka ununuzi/uuzaji wa mali za muda mrefu — majengo, magari, vifaa. Kawaida ni hasi (tunaununua zaidi ya kuuza).</li><li><strong>Financing Activities:</strong> Pesa kutoka kukopa au kulipa mikopo, kutoa hisa, kulipa gawio (dividends).</li></ul><h3>Indirect Method (Kawaida Zaidi)</h3><pre>Net Income                          1,400,000\nMarekebisho:\n  + Depreciation (non-cash)           200,000\n  + Decrease in AR (pesa ilipokuja)   100,000\n  - Increase in Inventory (pesa ilitoka) (300,000)\n  + Increase in AP (tulipata mkopo)   150,000\n═══════════════════════════════\nCash from Operating                 1,550,000</pre><blockquote><strong>Somo Muhimu:</strong> "Profit is opinion, Cash is fact." Kampuni nyingi zinaanguka wakati zina "faida" lakini hazina pesa ya kulipa mishahara au wasambazaji. Fuatilia Cash Flow kila wakati.</blockquote>');
        $this->assignment($l, 'Andaa Cash Flow Statement', 'Kutoka kwa taarifa za Income Statement na mabadiliko ya Balance Sheet, andaa Cash Flow Statement kwa mwaka 2024 kwa Indirect Method: Net Income = TZS 1.4M, Depreciation = TZS 200K, AR iliongezeka TZS 300K, Inventory ilipungua TZS 150K, AP iliongezeka TZS 200K, Bidhaa mpya zilinunuliwa TZS 800K, Mkopo ulipigwa TZS 500K. Hesabu net cash kwa sehemu zote tatu. Wasilisha Excel au PDF.', 90, 12);

        $l = $this->lesson($m2, 4, 'Financial Ratios na Uchambuzi', 'Jinsi ya kutumia ratios kuchambua afya ya kampuni: Liquidity ratios, Profitability ratios, Leverage ratios.', 1200,
            [['video_youtube', 'Financial Ratio Analysis', 'https://www.youtube.com/watch?v=OMA6MnPxHLg']],
            '<h2>Financial Ratios — Kipimo cha Afya ya Kampuni</h2><p>Ratio analysis inakuruhusu kulinganisha hali ya kampuni na: (1) Hali yake ya mwaka uliopita, (2) Kampuni nyingine katika sekta hiyo, (3) Viwango vya kawaida vya sekta.</p><h3>Liquidity Ratios (Uwezo wa Kulipa Madeni ya Muda Mfupi)</h3><ul><li><strong>Current Ratio:</strong> Current Assets ÷ Current Liabilities. Tarajiwa: zaidi ya 2. Chini ya 1 = hatari!</li><li><strong>Quick Ratio:</strong> (Current Assets - Inventory) ÷ Current Liabilities. Tarajiwa: zaidi ya 1.</li></ul><h3>Profitability Ratios (Uwezo wa Kufanya Faida)</h3><ul><li><strong>Gross Profit Margin:</strong> Gross Profit ÷ Revenue × 100</li><li><strong>Net Profit Margin:</strong> Net Income ÷ Revenue × 100</li><li><strong>Return on Equity (ROE):</strong> Net Income ÷ Shareholders Equity × 100</li><li><strong>Return on Assets (ROA):</strong> Net Income ÷ Total Assets × 100</li></ul><h3>Leverage/Solvency Ratios (Madeni)</h3><ul><li><strong>Debt-to-Equity Ratio:</strong> Total Debt ÷ Total Equity. Tarajiwa: chini ya 2.</li><li><strong>Interest Coverage Ratio:</strong> EBIT ÷ Interest Expense. Tarajiwa: zaidi ya 3.</li></ul><blockquote><strong>Kanuni:</strong> Ratio moja haisemi kitu — linganisha ratios nyingi pamoja na tazama mwelekeo kwa miaka 3+. Ukuaji wa ROE wakati Debt inakua pia — angalia kwa makini, labda inakua kwa hatari.</blockquote>');
        $this->assignment($l, 'Uchambuzi wa Fedha wa Kampuni', 'Pewa taarifa za fedha za kampuni mbili katika sekta moja (au unda mwenyewe). Hesabu ratios hizi kwa kila kampuni: (1) Current Ratio, (2) Quick Ratio, (3) Gross Profit Margin, (4) Net Profit Margin, (5) ROE, (6) Debt-to-Equity Ratio. Andika uchambuzi: kampuni ipi ina afya bora ya fedha? Kwa nini? Wasilisha Excel (hesabu) + ripoti fupi (.docx)', 100, 14);

        $m3 = $this->mod($course, 3, 'Viwango vya IFRS (International Financial Reporting Standards)', 'Viwango vya uhasibu vinavyotumika duniani — IFRS 15, 16, IAS 36, na vingine.');

        $l = $this->lesson($m3, 1, 'IFRS ni Nini na Kwa Nini Zinatumika?', 'Historia ya IFRS, tofauti kati ya IFRS na local GAAP, nchi zinazotumia IFRS, na umuhimu wa ulinganifu wa kimataifa.', 1080,
            [['video_youtube', 'IFRS Introduction — Kwa Beginners', 'https://www.youtube.com/watch?v=Xo-UR8PEZS8']],
            '<h2>IFRS — Viwango vya Uhasibu vya Kimataifa</h2><p>IFRS (International Financial Reporting Standards) ni mfumo wa viwango vya uhasibu vilivyoandikwa na IASB (International Accounting Standards Board) vinavyotumika katika nchi zaidi ya 140 duniani.</p><h3>Historia ya IFRS</h3><ul><li><strong>1973:</strong> IASC (International Accounting Standards Committee) iliundwa — iliandika IAS standards</li><li><strong>2001:</strong> IASC ilifanywa upya kuwa IASB — ilianza kutoa IFRS standards</li><li><strong>2005:</strong> EU ilihitaji kampuni zake zote kubwa kutumia IFRS</li><li><strong>Leo:</strong> Tanzania, Kenya, Africa Kusini, na nchi nyingi za Afrika zinatumia IFRS</li></ul><h3>IFRS vs Local GAAP — Tofauti Kuu</h3><ul><li><strong>IFRS:</strong> Inategemea kanuni (principles-based) — inatoa mwongozo mkuu, uamuzi zaidi</li><li><strong>US GAAP:</strong> Inategemea sheria (rules-based) — sheria nyingi maalum, flexibility kidogo</li></ul><h3>Faida za IFRS</h3><ul><li>Ulinganisho wa kimataifa — wawekezaji wa nje wanaweza kuelewa taarifa zako</li><li>Uwazi zaidi — waaminifu zaidi kwa wawekezaji</li><li>Urahisi wa kukopa kimataifa — benki za kimataifa zinakuamini zaidi</li></ul><blockquote><strong>Tanzania:</strong> Kampuni zote zinazoorodheshwa DSE (Dar es Salaam Stock Exchange) lazima zitumie IFRS. Kampuni ndogo zinatumia IFRS for SMEs — toleo lililorahisishwa.</blockquote>');
        $this->assignment($l, 'Utafiti wa IFRS katika Tanzania', 'Fanya utafiti na andika ripoti fupi (ukurasa 1-2): (1) Je, Tanzania inatumia IFRS au local GAAP? Tangu lini?, (2) Kampuni 3 zilizoorodheshwa DSE — zinatumia IFRS?, (3) Orodhesha IFRS/IAS standards 5 unazozijua na kazi yake kwa ufupi, (4) Tofauti kuu 3 kati ya IFRS na uhasibu wa kawaida unavyoujua, (5) Kwa nini kampuni ndogo huhitaji kujali IFRS? Wasilisha ripoti (.docx).', 50, 7);

        $l = $this->lesson($m3, 2, 'IFRS 15 — Utambuzi wa Mapato (Revenue Recognition)', 'Hatua 5 za kutambua mapato kulingana na IFRS 15. Mifano ya mikataba ngumu — subscription services, long-term projects.', 1440,
            [['video_youtube', 'IFRS 15 Revenue Recognition Explained', 'https://www.youtube.com/watch?v=yvHFmWHBJCo']],
            '<h2>IFRS 15 — Lini Kutambua Mapato?</h2><p>IFRS 15 inajishughulisha na swali moja muhimu: <strong>Mapato yanatambuliwa lini?</strong> Si wakati wa kuandika invoice, wala wakati wa kulipwa — bali wakati kampuni inapomaliza "wajibu wake wa utendaji" (performance obligation).</p><h3>Hatua 5 za IFRS 15</h3><ol><li><strong>Tambua Mkataba:</strong> Je, kuna mkataba wa kisheria/biashara na mteja?</li><li><strong>Tambua Performance Obligations:</strong> Kampuni inapaswa kufanya nini? (mfano: kutoa bidhaa, kutoa mafunzo, kutoa usaidizi — hizi ni 3 tofauti)</li><li><strong>Hesabu Transaction Price:</strong> Jumla ya pesa utakayopokea (ikihusisha discounts, variable consideration)</li><li><strong>Gawanya Transaction Price:</strong> Gawanya bei kwa kila performance obligation kulingana na bei yake ya standalone</li><li><strong>Tambua Mapato:</strong> Tambua mapato ya kila obligation UNAPOPOKUWA unaitekeleza</li></ol><h3>Mfano wa Kawaida</h3><p>Kampuni ya software inauza: Leseni (TZS 8M) + Mafunzo wiki 2 (TZS 1.5M) + Usaidizi wa mwaka (TZS 0.5M) = Jumla TZS 10M. Mapato yanagawanywa katika 3 na yanatambuliwa tofauti tofauti.</p><blockquote><strong>Kabla ya IFRS 15:</strong> IAS 18 ilikuwa rahisi lakini haikutosha kwa mikataba ngumu ya kisasa. IFRS 15 inatatua hilo kwa kufafanua "lini" kwa uwazi zaidi.</blockquote>');
        $this->assignment($l, 'IFRS 15 — Revenue Recognition Case Study', 'Kampuni ya software inauza package moja: Leseni ya programu TZS 10M kwa miaka 3, Mafunzo ya wiki 2 TZS 2M, na Usaidizi wa kila mwaka TZS 1.5M/mwaka. Kwa kutumia IFRS 15 five-step model: (1) Tambua performance obligations, (2) Hesabu Standalone Selling Price ya kila obligation, (3) Gawanya TZS 10M+2M+4.5M (jumla = TZS 16.5M) kwa kila obligation, (4) Onyesha jinsi ya kutambua mapato kwa miaka 3 kwa kila obligation. Wasilisha Excel + maelezo.', 100, 14);

        $l = $this->lesson($m3, 3, 'IFRS 16 — Mikataba ya Kukodisha (Leases)', 'Jinsi IFRS 16 ilibadilisha jinsi kampuni zinavyoonyesha mikataba ya kukodisha katika balance sheet. Right-of-use assets na lease liabilities.', 1200,
            [['video_youtube', 'IFRS 16 Leases Simplified', 'https://www.youtube.com/watch?v=zM38bFHqfVo']],
            '<h2>IFRS 16 — Kukodisha na Balance Sheet</h2><p>Kabla ya IFRS 16 (iliyotumika 2019), makampuni mengi yalikodisha majengo, magari, na vifaa na kuyafunua nje ya balance sheet ("off-balance sheet financing"). Hii ilimaanisha madeni halisi hayakuonekana.</p><h3>Mabadiliko ya IFRS 16</h3><p>IFRS 16 inasema: ukikodisha kitu kwa muda mrefu (zaidi ya miaka 1), lazima uliweke katika Balance Sheet kama:</p><ul><li><strong>Right-of-Use (ROU) Asset:</strong> Haki ya kutumia mali — upande wa Assets</li><li><strong>Lease Liability:</strong> Wajibu wa kulipa — upande wa Liabilities</li></ul><h3>Athari kwa Financial Statements</h3><ul><li><strong>Balance Sheet:</strong> Assets zinaongezeka (ROU), Liabilities zinaongezeka — leverage ratio inabadilika</li><li><strong>Income Statement:</strong> Kodi (lease expense) inabadilika — badala yake: Depreciation ya ROU + Riba ya Lease Liability</li><li><strong>Cash Flow:</strong> Malipo ya lease yanaonekana katika Financing Activities (si Operating)</li></ul><h3>Exemptions (Exceptions)</h3><p>IFRS 16 haitumiki kwa: (1) Leases za muda mfupi (&lt; 12 miezi), (2) Leases za mali za thamani ndogo (&lt; $5,000)</p><blockquote><strong>Athari ya Kweli:</strong> Makampuni ya ndege (airlines) yaliona Assets na Liabilities zikaongezeka kwa mabilioni baada ya IFRS 16. Ratios zilibadilika sana — wawekezaji walipaswa kujua hili.</blockquote>');
        $this->assignment($l, 'Hesabu ya Lease kwa IFRS 16', 'Kampuni inakodisha ofisi kwa miaka 5. Kodi ya kila mwaka = TZS 1,200,000. Discount rate = 8% kwa mwaka. Fanya yafuatayo: (1) Hesabu Present Value ya lease payments (PV ya annuity ya miaka 5 kwa 8%), (2) Rekodi ROU Asset na Lease Liability siku ya kwanza (hizi zote mbili = PV), (3) Tengeneza schedule ya amortization ya lease kwa miaka 5 (Onyesha: Mwaka, Malipo, Riba 8%, Mwili wa Deni, Deni Linalobaki), (4) Journal entry ya mwaka 1: Dr Depreciation + Dr Interest / Cr Cash. Wasilisha Excel.', 100, 14);

        $l = $this->lesson($m3, 4, 'IAS 36 — Kupungua kwa Thamani ya Mali (Impairment)', 'Jinsi ya kujua kama mali ina impairment, jinsi ya kuhesabu, na jinsi ya kurekodi. Cash Generating Units (CGUs).', 1080,
            [['video_youtube', 'IAS 36 Impairment of Assets', 'https://www.youtube.com/watch?v=2R1gw9QZFYI']],
            '<h2>IAS 36 — Impairment: Wakati Mali Inapoteza Thamani</h2><p>IAS 36 inasema: <strong>mali haipaswi kuonekana katika taarifa za fedha kwa thamani zaidi ya inayoweza kupatikana</strong>. Ukiwa na mali yenye thamani ya TZS 5M lakini soko linasema inastahili TZS 3M — lazima ushushe thamani (impairment).</p><h3>Ishara za Impairment (Indicators)</h3><ul><li>Bei ya soko imeshuka zaidi ya kawaida</li><li>Mabadiliko ya teknolojia — mali imepitwa na wakati</li><li>Uharibifu wa kimwili wa mali</li><li>Uchumi umezorota — kampuni inafanya hasara</li><li>Mpango wa kuuza mali mapema</li></ul><h3>Kuhesabu Impairment</h3><p>Hatua 1: Hesabu Recoverable Amount = MAX (Fair Value Less Costs to Sell, Value in Use)</p><p>Hatua 2: Linganisha na Carrying Amount (Book Value katika vitabu)</p><p>Hatua 3: Kama Carrying Amount > Recoverable Amount → Impairment Loss = tofauti kati ya hizo</p><h3>Cash Generating Units (CGUs)</h3><p>Mali nyingi huwezi kuhesabu impairment yake peke yake — inafanya kazi pamoja na mali nyingine. Kwa hiyo IAS 36 inahitaji kutathmini "CGU" — kundi dogo zaidi la mali zinazozalisha pesa pamoja.</p><blockquote><strong>Mfano:</strong> Kampuni inamiliki hoteli ambayo bei yake ya soko imeshuka kutoka TZS 10M hadi TZS 6M. Carrying amount ni TZS 8M. Impairment Loss = TZS 2M. Hii inaonekana katika Income Statement kama gharama.</blockquote>');
        $this->assignment($l, 'Impairment Test kwa IAS 36', 'Kampuni inamiliki vifaa vya uzalishaji (factory equipment) na data hii: Carrying Amount (Book Value) = TZS 8,000,000, Fair Value Less Costs to Sell = TZS 5,500,000, Value in Use (PV ya cash flows za baadaye) = TZS 6,200,000. Fanya: (1) Hesabu Recoverable Amount, (2) Je, kuna impairment? Kwa kiasi gani?, (3) Rekodi journal entry ya impairment, (4) Jinsi gani Balance Sheet na Income Statement vitabadilika?, (5) Kama mwaka ujao Value in Use inarudi TZS 7,500,000 — je reversal inaruhusiwa chini ya IAS 36? Wasilisha Excel + maelezo.', 100, 14);
    }

    // =========================================================================
    // COURSE 5 — Python for Data Analytics
    // =========================================================================
    private function pythonCourse(int $trainerId): void
    {
        $course = Course::updateOrCreate(
            ['title' => 'Python kwa Uchambuzi wa Data (Data Analytics)'],
            [
                'description'    => 'Jifunza Python kutoka mwanzo kabisa hadi kiwango cha kuchambua data kwa ufanisi. Pandas, NumPy, Matplotlib, na Seaborn — zana ambazo zinatumika na wachunguzi wa data duniani kote.',
                'category'       => 'data_analytics',
                'level'          => 'intermediate',
                'duration_hours' => 25,
                'price_tzs'      => 0,
                'instructor_id'  => $trainerId,
                'created_by'     => $trainerId,
                'status'         => 'published',
                'published_at'   => now(),
                'approved_at'    => now(),
            ]
        );

        $m1 = $this->mod($course, 1, 'Python — Misingi ya Lugha', 'Variables, data types, control flow, functions. Unahitaji kujua hivi kabla ya kuanza data analysis.');

        $l = $this->lesson($m1, 1, 'Kuanzisha Python na Jupyter Notebook', 'Jinsi ya kuinstall Python, pip, na Jupyter Notebook. Kuelewa environment ya kufanya kazi. Hello World ya kwanza.', 900,
            [['video_youtube', 'Kuanza Python na Jupyter Notebook', 'https://www.youtube.com/watch?v=YYXdXT2l-Gg']],
            '<h2>Kuanza na Python na Jupyter Notebook</h2><p>Python ni lugha ya programu inayopendwa zaidi duniani kwa data science, AI, na automation. Ni rahisi kusoma na kuandika — inafanana na Kiingereza.</p><h3>Jinsi ya Kuinstall</h3><ol><li>Pakua <strong>Anaconda</strong> kutoka anaconda.com — inajumuisha Python, Jupyter, na packages nyingi za data science mara moja</li><li>Au tumia Google Colab (colab.research.google.com) — bila kuinstall chochote! Inafanya kazi kwenye browser</li><li>Au VSCode na Python extension — kwa wanaopenda editor</li></ol><h3>Jupyter Notebook — Chombo cha Data Scientists</h3><ul><li>Ni kama notebook ya kawaida lakini unaweza kuandika code na kuona matokeo moja kwa moja</li><li>Cells: Code cells (Python), Markdown cells (maelezo)</li><li><code>Shift + Enter</code> — run cell na nenda chini</li><li><code>Ctrl + Enter</code> — run cell na kaa hapo hapo</li></ul><h3>Hello World ya Kwanza</h3><pre><code># Hii ni comment — Python haisomi hii\nprint("Habari Dunia!")  # Onyesha text\nprint(2 + 2)            # Onyesha hesabu\nx = 10\nprint(f"Jibu ni: {x}")  # f-string</code></pre><blockquote><strong>Ushauri:</strong> Tumia Google Colab kama unaanza — unaweza kufanya kazi bila kuinstall chochote, na hata kushiriki notebook na wengine kama Google Docs.</blockquote>');
        $this->assignment($l, 'Jupyter Notebook ya Kwanza', 'Unda Jupyter Notebook (au Google Colab) na ufanye yafuatayo: (1) Cell ya Markdown: andika jina lako, tarehe, na malengo ya kujifunza Python, (2) Cell ya code: print maneno matano ya Kiswahili, (3) Cell ya code: hesabu 5 operations za msingi (+, -, *, /, **), (4) Cell ya code: unda variable ya jina lako na uitumie katika print, (5) Onyesha matokeo ya kila cell. Wasilisha .ipynb au link ya Colab.', 40, 4);

        $l = $this->lesson($m1, 2, 'Variables, Data Types, na Operators', 'int, float, string, bool, list, dict, tuple. Jinsi ya kutangaza variables na kufanya operations za msingi.', 1080,
            [['video_youtube', 'Python Data Types na Variables', 'https://www.youtube.com/watch?v=khKv-8q7YmY']],
            '<h2>Variables na Data Types katika Python</h2><p>Variable ni chombo cha kuhifadhi thamani. Tofauti na Excel, Python ina aina maalum za data na kila aina ina tabia yake.</p><h3>Aina Kuu za Data</h3><pre><code># int — nambari kamili\numri = 25\nidadi = -10\n\n# float — nambari za desimali\nbei = 1500.50\nkiwango = 3.14\n\n# str — text (string)\njina = "Hamisi"\njibu = \'Ndio\'\n\n# bool — kweli au uongo\nni_mwanafunzi = True\nimeisha = False\n\n# Angalia aina: type(variable)\nprint(type(umri))   # &lt;class \'int\'&gt;</code></pre><h3>Collections (Makusanyo)</h3><pre><code># list — orodha inayobadilika\nmatunda = ["embe", "ndizi", "papai"]\nmatunda.append("chungwa")   # ongeza\n\n# tuple — orodha isiyobadilika\nrangi = ("nyekundu", "kijani", "bluu")\n\n# dict — key-value pairs\nmwanafunzi = {"jina": "Ali", "umri": 20, "daraja": "A"}\nprint(mwanafunzi["jina"])  # Ali\n\n# set — unique values tu\nnambari = {1, 2, 3, 2, 1}  # {1, 2, 3}</code></pre><h3>Type Conversion</h3><pre><code>int("42")     # "42" → 42\nfloat(10)     # 10 → 10.0\nstr(3.14)     # 3.14 → "3.14"\nbool(0)       # 0 → False, kitu chochote → True</code></pre><blockquote><strong>Kumbuka:</strong> Python ni "dynamically typed" — huhitaji kutangaza aina ya data. Python inagundua yenyewe. Lakini ni vizuri kujua aina za data ili kuepuka makosa.</blockquote>');
        $this->assignment($l, 'Calculator ya Biashara kwa Python', 'Andika Python script inayofanya yafuatayo: (1) Unda dictionary ya bidhaa 5 na bei zao: {"mkate": 2000, "sukari": 5000, ...}, (2) Unda list ya bidhaa alizochagua mteja (angalau 3), (3) Hesabu jumla ya bei ya manunuzi, (4) Hesabu VAT (18%) na jumla ya kulipia, (5) Onyesha receipt ya manunuzi kwa format nzuri kwa print. Wasilisha .py au .ipynb.', 55, 6);

        $l = $this->lesson($m1, 3, 'Control Flow: if/elif/else, for loops, while', 'Kuamua na kurudia — jinsi Python inavyofanya maamuzi na jinsi ya kurudia kazi nyingi kiotomatiki.', 1200,
            [['video_youtube', 'Python Control Flow — Loops na Conditionals', 'https://www.youtube.com/watch?v=DZwmZ8Usvnk']],
            '<h2>Control Flow — Jinsi Python Inavyofanya Maamuzi na Loops</h2><p>Control flow inafanya programu yako "ifikirie" na "irudie" — bila hii, code yako ingefanya mambo yale yale tu kila wakati.</p><h3>if/elif/else — Maamuzi</h3><pre><code>alama = 75\n\nif alama >= 80:\n    daraja = "A"\nelif alama >= 65:\n    daraja = "B"\nelif alama >= 50:\n    daraja = "C"\nelse:\n    daraja = "F"\n\nprint(f"Daraja lako: {daraja}")</code></pre><h3>for Loop — Rudia kwa Kila Kipande</h3><pre><code># Pita kwenye list\nmatunda = ["embe", "ndizi", "papai"]\nfor tunda in matunda:\n    print(f"Ninapenda {tunda}")\n\n# range() — nambari\nfor i in range(1, 11):  # 1 hadi 10\n    print(i * 2)  # Jedwali la 2\n\n# enumerate — thamani na index\nfor i, tunda in enumerate(matunda):\n    print(f"{i+1}. {tunda}")</code></pre><h3>while Loop — Rudia hadi Sharti Litimie</h3><pre><code>nambari = 1\nwhile nambari <= 10:\n    print(nambari)\n    nambari += 1  # Muhimu! Bila hii loop haitaisha</code></pre><h3>break na continue</h3><pre><code>for i in range(10):\n    if i == 5:\n        break      # Simama kabisa\n    if i % 2 == 0:\n        continue   # Ruka iteration hii\n    print(i)       # Inaprint 1, 3 tu</code></pre><blockquote><strong>Onyo:</strong> while loop inaweza kuendelea milele ukisahau kubadilisha sharti. Ukiganda loop isiyokwisha, bonyeza <code>Ctrl+C</code> kuisimamisha.</blockquote>');
        $this->assignment($l, 'Mchezo wa Kukadiria Nambari', 'Andika Python script ya mchezo wa kukadiria nambari: (1) Python ichague nambari ya siri kati ya 1-100 kwa random.randint(), (2) Mtumiaji aingie nadhani yake, (3) Python iseme "Juu zaidi" au "Chini zaidi" au "Sahihi!", (4) Hesabu idadi ya majaribio, (5) Baada ya mshindi, ulizie mtumiaji kama atacheza tena. Tumia while loop na if/elif/else. Wasilisha .py au .ipynb.', 65, 7);

        $l = $this->lesson($m1, 4, 'Functions na Modules', 'Jinsi ya kuandika functions reusable. Kuimport modules (math, os, datetime). Packages na pip install.', 1200,
            [['video_youtube', 'Python Functions na Modules', 'https://www.youtube.com/watch?v=9Os0o3wzS_I']],
            '<h2>Functions na Modules — Code Inayoweza Kutumika Tena</h2><p>Function ni kipande cha code ambacho unaweza kukiita mara nyingi bila kuandika upya. Modules ni files za Python zenye functions nyingi zilizoundwa na wengine.</p><h3>Kuunda Function</h3><pre><code>def salamu(jina, lugha="Swahili"):\n    """Sema salamu kwa lugha tofauti."""\n    if lugha == "Swahili":\n        return f"Habari {jina}!"\n    elif lugha == "English":\n        return f"Hello {jina}!"\n    else:\n        return f"Salut {jina}!"\n\nprint(salamu("Ali"))             # Habari Ali!\nprint(salamu("Bob", "English"))  # Hello Bob!</code></pre><h3>Lambda Functions (Anonymous)</h3><pre><code>double = lambda x: x * 2\nprint(double(5))  # 10\n\n# Mfano mzuri na sorted()\nwatu = [("Ali", 25), ("Fatuma", 30), ("Bob", 20)]\nwatu_sorted = sorted(watu, key=lambda x: x[1])\nprint(watu_sorted)  # Imepangwa kwa umri</code></pre><h3>Modules za Msingi</h3><pre><code>import math\nprint(math.sqrt(16))   # 4.0\nprint(math.pi)         # 3.14159...\n\nimport random\nprint(random.randint(1, 100))   # Nambari random 1-100\n\nfrom datetime import date\nleo = date.today()\nprint(leo)  # 2024-01-15\n\nimport os\nprint(os.getcwd())  # Current directory</code></pre><h3>pip — Kuinstall Packages</h3><pre><code># Terminal/Command Prompt\npip install pandas\npip install matplotlib\npip install seaborn</code></pre><blockquote><strong>Kanuni Nzuri:</strong> Kila function ifanye kitu kimoja tu na kwa uzuri. Ukiandika function inayofanya mambo 5 tofauti — igawanye kuwa functions 5. Hii inaitwa "Single Responsibility Principle".</blockquote>');
        $this->assignment($l, 'Python Functions za Biashara', 'Andika script ya Python yenye module yako mwenyewe ("biashara_tools.py") yenye functions hizi: (1) hesabu_vat(bei, kiwango=0.18) — irudishe bei + VAT, (2) format_sarafu(kiasi, sarafu="TZS") — irudishe "TZS 1,500,000", (3) kategoria_matumizi(kiasi) → "Chini" (<100K), "Kati" (100K-500K), "Juu" (>500K), (4) hesabu_faida(mapato, gharama) → tuple ya (faida, margin_percent). Katika file nyingine, import module yako na jaribu kila function na mifano 3. Wasilisha .py files zote mbili.', 70, 7);

        $m2 = $this->mod($course, 2, 'Pandas — Maktaba ya Data Analysis', 'Pandas ni maktaba muhimu zaidi ya Python kwa data analysis. DataFrames, Series, filtering, grouping.');

        $l = $this->lesson($m2, 1, 'Pandas Basics — Series na DataFrame', 'Jinsi ya kuunda na kusoma DataFrames. Loading data kutoka CSV, Excel, na JSON. info(), describe(), head().', 1440,
            [['video_youtube', 'Pandas Tutorial — Kuanza na DataFrames', 'https://www.youtube.com/watch?v=vmEHCJofslg']],
            '<h2>Pandas — Maktaba ya Data Analysis kwa Python</h2><p>Pandas inakupa uwezo wa Excel ndani ya Python — table (DataFrame) unayoweza kuchanganua, kusafisha, na kubadilisha kwa code. Inafanya kazi vizuri na data kubwa zaidi ya Excel.</p><h3>Series vs DataFrame</h3><pre><code>import pandas as pd\n\n# Series — safu wima moja\nbei = pd.Series([1000, 2500, 500, 1800], name="Bei")\nprint(bei)\n\n# DataFrame — table kamili\ndata = {\n    "Bidhaa": ["Mkate", "Sukari", "Mafuta"],\n    "Bei": [2000, 5000, 8000],\n    "Idadi": [50, 30, 20]\n}\ndf = pd.DataFrame(data)\nprint(df)</code></pre><h3>Kupakia Data</h3><pre><code># Kutoka CSV\ndf = pd.read_csv("mauzo.csv")\n\n# Kutoka Excel\ndf = pd.read_excel("mauzo.xlsx", sheet_name="Sheet1")\n\n# Kutoka JSON\ndf = pd.read_json("data.json")</code></pre><h3>Kuchunguza DataFrame</h3><pre><code>df.head(5)          # Rows 5 za kwanza\ndf.tail(5)          # Rows 5 za mwisho\ndf.info()           # Aina za data na nulls\ndf.describe()       # Statistics za nambari\ndf.shape            # (rows, columns)\ndf.columns          # Majina ya columns\ndf.dtypes           # Aina ya kila column</code></pre><blockquote><strong>Pandas vs Excel:</strong> Pandas inafanya kazi na files kubwa (milioni za rows), inafanya kila hatua kuwa reproducible (code), na inaweza kuunganishwa na visualization libraries. Excel inashinda kwa interactivity na speed ya kuchunguza data ndogo.</blockquote>');
        $this->assignment($l, 'Chunguza Dataset Mpya', 'Pakua dataset ya umma (Kaggle, UCI ML Repository, au data.gov). Weka kwenye Jupyter Notebook na ufanye: (1) df.info() — eleza aina za data na null values, (2) df.describe() — eleza statistics (mean, std, min, max), (3) Hesabu null values kwa kila column, (4) Onyesha unique values za columns za categorical, (5) Hesabu correlation matrix ya columns za nambari. Andika observations 5 muhimu ulizogundua. Wasilisha .ipynb.', 70, 8);

        $l = $this->lesson($m2, 2, 'Data Selection, Filtering, na Sorting', 'loc vs iloc, boolean filtering, query(), sort_values(). Jinsi ya kupata data unayoitaka haraka.', 1440,
            [['video_youtube', 'Pandas Data Selection na Filtering', 'https://www.youtube.com/watch?v=txMdrV1Ut64']],
            '<h2>Kuchagua na Kuchuja Data katika Pandas</h2><p>Kuchagua sehemu fulani ya DataFrame ni moja ya kazi za kawaida zaidi katika data analysis. Pandas ina njia nyingi za kufanya hivi.</p><h3>Kuchagua Columns</h3><pre><code># Column moja — inatoa Series\ndf["Jina"]\ndf.Jina\n\n# Columns nyingi — inatoa DataFrame\ndf[["Jina", "Bei", "Mkoa"]]</code></pre><h3>Kuchagua Rows — loc vs iloc</h3><pre><code># loc — kwa index label au boolean\ndf.loc[0]              # Row na index 0\ndf.loc[0:5]            # Rows 0-5 (inclusive!)\ndf.loc[df["Bei"] > 1000]  # Boolean filter\n\n# iloc — kwa position (kama array)\ndf.iloc[0]             # Row ya kwanza\ndf.iloc[0:5]           # Rows 0-4 (exclusive!)\ndf.iloc[:, 2]          # Column ya 3 (index 2)</code></pre><h3>Boolean Filtering</h3><pre><code># Filter moja\ndf_dar = df[df["Mkoa"] == "Dar es Salaam"]\n\n# Filter nyingi\ndf_filtered = df[(df["Bei"] > 1000) &amp; (df["Mkoa"] == "Dar")]\n\n# isin() — thamani nyingi\ndf_pwani = df[df["Mkoa"].isin(["Dar", "Tanga", "Mtwara"])]</code></pre><h3>Sorting na Query</h3><pre><code># Sort kwa column\ndf_sorted = df.sort_values("Bei", ascending=False)\n\n# Sort kwa columns nyingi\ndf.sort_values(["Mkoa", "Bei"], ascending=[True, False])\n\n# query() — syntax rahisi\ndf.query("Bei > 1000 and Mkoa == \'Dar\'")</code></pre><blockquote><strong>Makosa ya Kawaida:</strong> Unapofanya df.loc[df["Mkoa"] == "Dar"], ukisahau maandishi sahihi (case sensitive!), hutapata results. Tumia df["Mkoa"].str.lower() == "dar" kama data haina uhakika wa case.</blockquote>');
        $this->assignment($l, 'Uchunguzi wa Dataset kwa Filtering', 'Kutumia dataset yako (au dataset ya mauzo), fanya uchunguzi huu: (1) Chagua rows 3 za kwanza na 3 za mwisho kwa loc na iloc, (2) Filter bidhaa zenye bei zaidi ya wastani, (3) Chagua data ya mkoa mmoja tu kwa boolean filter, (4) Pata bidhaa 5 zinazouza vizuri zaidi kwa sort_values, (5) Tumia query() kupata: mauzo zaidi ya 100K NA mkoa ni moja ya "Dar", "Mwanza", "Arusha". Wasilisha .ipynb.', 75, 8);

        $l = $this->lesson($m2, 3, 'GroupBy, Aggregation, na Pivot Tables', 'groupby() ni mfano wa PivotTable lakini kwa nguvu zaidi. agg(), pivot_table(). Mifano ya kweli ya biashara.', 1440,
            [['video_youtube', 'Pandas GroupBy na Aggregation', 'https://www.youtube.com/watch?v=Wb2Tp35dZ-I']],
            '<h2>GroupBy na Aggregation — Kama PivotTable lakini kwa Python</h2><p>GroupBy inakuruhusu kugawanya data katika makundi na kufanya hesabu kwa kila kundi. Hii ndiyo mojawapo ya operesheni muhimu zaidi katika data analysis.</p><h3>groupby() — Msingi</h3><pre><code>import pandas as pd\n\n# Jumla ya mauzo kwa kila mkoa\njumla_kwa_mkoa = df.groupby("Mkoa")["Mauzo"].sum()\n\n# Wastani wa bei kwa kila aina ya bidhaa\nwastani_bei = df.groupby("Bidhaa")["Bei"].mean()\n\n# Hesabu ya orders kwa kila mwezi\norders_mwezi = df.groupby("Mwezi")["Order_ID"].count()</code></pre><h3>agg() — Aggregation Nyingi kwa Wakati Mmoja</h3><pre><code>matokeo = df.groupby("Mkoa").agg(\n    jumla_mauzo=("Mauzo", "sum"),\n    wastani_mauzo=("Mauzo", "mean"),\n    idadi_orders=("Order_ID", "count"),\n    mauzo_makubwa=("Mauzo", "max")\n).reset_index()\nprint(matokeo)</code></pre><h3>pivot_table() — Kama Excel PivotTable</h3><pre><code># Mauzo kwa Mkoa (rows) na Mwezi (columns)\npivot = df.pivot_table(\n    values="Mauzo",\n    index="Mkoa",\n    columns="Mwezi",\n    aggfunc="sum",\n    fill_value=0\n)\nprint(pivot)</code></pre><blockquote><strong>Pandas Profiling:</strong> Kwa uchunguzi wa haraka wa dataset nzima, tumia: <code>from pandas_profiling import ProfileReport; ProfileReport(df).to_notebook_iframe()</code> — inatoa ripoti kamili ya EDA kwa mistari 2 ya code!</blockquote>');
        $this->assignment($l, 'Ripoti ya Mauzo kwa GroupBy', 'Kutumia dataset ya mauzo (CSV yenye columns: Tarehe, Bidhaa, Mkoa, Idadi, Bei, Kategoria): (1) Hesabu jumla ya mauzo kwa kila mkoa kwa groupby, (2) Pata bidhaa 5 zenye wastani wa bei wa juu kwa agg(), (3) Unda pivot_table ya jumla ya mauzo kwa Mkoa (rows) na Mwezi (columns), (4) Hesabu % ya mauzo ya kila mkoa kwa jumla, (5) Pata mwezi wenye mauzo makubwa kwa kila aina ya bidhaa. Wasilisha .ipynb.', 90, 10);

        $l = $this->lesson($m2, 4, 'Cleaning Data kwa Pandas', 'Kushughulikia missing values (NaN), duplicates, outliers, na data ya aina tofauti. Pandas ni chombo bora cha data cleaning.', 1200,
            [['video_youtube', 'Data Cleaning na Pandas', 'https://www.youtube.com/watch?v=ZOX18HfLHGQ']],
            '<h2>Data Cleaning kwa Pandas — Kusafisha Data Chafu</h2><p>Watafiti wa data wanasema 80% ya muda wao unatumika kusafisha data. Pandas ina zana nyingi za kufanya hivi haraka na kwa ufanisi.</p><h3>Missing Values (NaN)</h3><pre><code># Angalia missing values\ndf.isnull().sum()           # Jumla ya nulls kwa column\ndf.isnull().any()           # Columns zenye nulls\n\n# Futa rows zenye nulls\ndf_clean = df.dropna()      # Futa rows zote zenye null\ndf_clean = df.dropna(subset=["Bei", "Mkoa"])  # Specific columns\n\n# Jaza nulls\ndf["Bei"].fillna(df["Bei"].mean(), inplace=True)  # Jaza na wastani\ndf["Mkoa"].fillna("Haijulikani", inplace=True)    # Jaza na text</code></pre><h3>Duplicates</h3><pre><code>print(df.duplicated().sum())      # Hesabu duplicates\ndf_unique = df.drop_duplicates()  # Futa duplicates\n\n# Duplicates za columns fulani tu\ndf.drop_duplicates(subset=["Order_ID"], keep="first")</code></pre><h3>Data Type Conversion</h3><pre><code>df["Tarehe"] = pd.to_datetime(df["Tarehe"])\ndf["Bei"] = pd.to_numeric(df["Bei"], errors="coerce")  # "coerce" → NaN kwa errors\ndf["Mkoa"] = df["Mkoa"].astype(str).str.strip().str.title()</code></pre><h3>Outliers</h3><pre><code># IQR method\nQ1 = df["Bei"].quantile(0.25)\nQ3 = df["Bei"].quantile(0.75)\nIQR = Q3 - Q1\ndf_no_outliers = df[(df["Bei"] >= Q1 - 1.5*IQR) &amp; (df["Bei"] <= Q3 + 1.5*IQR)]</code></pre><blockquote><strong>Kanuni ya Msingi:</strong> Kamwe usifute data chafu bila kuiandika kwanza — hifadhi nakala ya original. Data "chafu" leo inaweza kuwa muhimu kesho.</blockquote>');
        $this->assignment($l, 'Data Cleaning Mradi', 'Pewa (au unda) dataset chafu yenye shida hizi: null values nyingi, duplicates, tarehe kama string, bei kama "TZS 5,000" (na alama), outliers (mauzo ya TZS -100 au TZS 1 bilioni). Safisha: (1) Hesabu na onyesha null values kabla ya kusafisha, (2) Jaza nulls kwa mbinu sahihi kwa kila column, (3) Futa duplicates, (4) Convert tarehe na bei kuwa aina sahihi, (5) Ondoa outliers kwa IQR method. Linganisha shape ya df kabla na baada. Wasilisha .ipynb.', 90, 10);

        $m3 = $this->mod($course, 3, 'Data Visualization na Mradi wa Mwisho', 'Matplotlib, Seaborn, na kuwasilisha matokeo ya data analysis kwa njia inayoeleweka.');

        $l = $this->lesson($m3, 1, 'Matplotlib — Misingi ya Visualization', 'line plot, bar chart, scatter plot, histogram, pie chart. Kuformat: titles, labels, colors, legend.', 1440,
            [['video_youtube', 'Matplotlib Tutorial — Jinsi ya Kuplot Data', 'https://www.youtube.com/watch?v=UO98lJQ3QGI']],
            '<h2>Matplotlib — Maktaba ya Visualization ya Python</h2><p>Matplotlib ni maktaba ya kawaida ya visualization katika Python. Inakupa udhibiti kamili wa kila kipande cha chart — hata kama syntax ni verbose kidogo.</p><h3>Muundo wa Msingi</h3><pre><code>import matplotlib.pyplot as plt\n\n# Unda figure na axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Data\nmwezi = ["Jan", "Feb", "Mar", "Apr", "Mei"]\nmauzo = [500000, 620000, 580000, 750000, 800000]\n\n# Plot\nax.plot(mwezi, mauzo, color="blue", linewidth=2, marker="o")\n\n# Format\nax.set_title("Mwelekeo wa Mauzo 2024", fontsize=16)\nax.set_xlabel("Mwezi")\nax.set_ylabel("Mauzo (TZS)")\nax.grid(True, alpha=0.3)\n\nplt.tight_layout()\nplt.savefig("mauzo.png", dpi=300)  # Hifadhi\nplt.show()</code></pre><h3>Aina za Charts</h3><pre><code># Bar chart\nax.bar(kategoria, thamani, color="steelblue")\n\n# Horizontal bar\nax.barh(kategoria, thamani)\n\n# Scatter plot\nax.scatter(x, y, c="red", s=50, alpha=0.6)\n\n# Histogram\nax.hist(data, bins=20, edgecolor="black")\n\n# Pie chart\nax.pie(thamani, labels=majina, autopct="%1.1f%%")</code></pre><h3>Subplots — Charts Nyingi</h3><pre><code>fig, axes = plt.subplots(2, 2, figsize=(12, 8))\naxes[0,0].plot(x, y1)  # Juu-kushoto\naxes[0,1].bar(x, y2)   # Juu-kulia\naxes[1,0].hist(data)    # Chini-kushoto\naxes[1,1].scatter(x,y3) # Chini-kulia</code></pre><blockquote><strong>Matplotlib vs Seaborn vs Plotly:</strong> Matplotlib = uwezo kamili, ngumu kidogo. Seaborn = rahisi, statistical. Plotly = interactive, vizuri kwa web. Jifunze Matplotlib kwanza — ndiyo msingi wa wote.</blockquote>');
        $this->assignment($l, 'Visualization ya Data ya Mauzo', 'Kutumia dataset ya mauzo yako, unda subplots figure yenye charts 4 (2×2 grid): (1) Line chart ya mwelekeo wa mauzo kwa mwezi, (2) Bar chart ya top 5 bidhaa kwa jumla ya mauzo, (3) Histogram ya distribution ya bei za bidhaa, (4) Pie chart ya sehemu ya mauzo kwa mkoa (top 5). Kila chart iwe na: title, axis labels, na colors nzuri. Hifadhi kama PNG 300dpi. Wasilisha .ipynb + PNG.', 85, 10);

        $l = $this->lesson($m3, 2, 'Seaborn — Statistical Visualizations', 'Seaborn inafanya statistical plots kuwa rahisi: heatmap, pairplot, boxplot, violin plot. Kuelewa distribution ya data.', 1200,
            [['video_youtube', 'Seaborn Tutorial kwa Data Scientists', 'https://www.youtube.com/watch?v=6GUZXDef2U0']],
            '<h2>Seaborn — Visualization ya Kisayansi</h2><p>Seaborn imejengwa juu ya Matplotlib lakini inafanya statistical visualizations kuwa rahisi zaidi na vizuri zaidi kwa code ndogo zaidi.</p><h3>Setup</h3><pre><code>import seaborn as sns\nimport matplotlib.pyplot as plt\n\nsns.set_style("whitegrid")  # Style ya background\nsns.set_palette("husl")     # Rangi nzuri</code></pre><h3>Charts za Msingi za Seaborn</h3><pre><code># Distribution ya data moja\nsns.histplot(data=df, x="Bei", bins=30, kde=True)\n\n# Boxplot — outliers na quartiles\nsns.boxplot(data=df, x="Mkoa", y="Mauzo")\n\n# Violin plot — distribution kwa kila category\nsns.violinplot(data=df, x="Kategoria", y="Bei")\n\n# Bar plot — na error bars kiotomatiki\nsns.barplot(data=df, x="Mkoa", y="Mauzo", estimator=sum)\n\n# Scatter plot na regression line\nsns.scatterplot(data=df, x="Bei", y="Mauzo", hue="Mkoa")\nsns.regplot(data=df, x="Bei", y="Mauzo")</code></pre><h3>Correlation Heatmap — Muhimu sana!</h3><pre><code>correlation = df.select_dtypes(include="number").corr()\nsns.heatmap(correlation, annot=True, cmap="coolwarm", fmt=".2f")\nplt.title("Correlation Matrix")\nplt.show()</code></pre><h3>Pairplot — Uchunguzi wa Haraka</h3><pre><code>sns.pairplot(df[["Bei", "Mauzo", "Idadi", "Faida"]], hue="Mkoa")</code></pre><blockquote><strong>Kuelewa Correlation:</strong> Correlation 1.0 = uhusiano kamili chanya. -1.0 = kinyume kamili. 0 = hakuna uhusiano. Ukiona correlation > 0.7 au < -0.7 kati ya variables mbili — hiyo ni habari muhimu!</blockquote>');
        $this->assignment($l, 'Statistical Visualization kwa Seaborn', 'Kutumia dataset yako, unda Seaborn visualizations: (1) Histplot + KDE ya mauzo — inaonyesha distribution, (2) Boxplot ya mauzo kwa mkoa — angalia outliers, (3) Heatmap ya correlation matrix ya columns zote za nambari — eleza correlations 2 muhimu, (4) Barplot ya wastani wa mauzo kwa kategoria, (5) Scatterplot ya Bei vs Mauzo ikiwa na hue ya Mkoa — je, kuna pattern? Andika maelezo ya kila chart. Wasilisha .ipynb.', 80, 9);

        $l = $this->lesson($m3, 3, 'Exploratory Data Analysis (EDA)', 'Mchakato kamili wa kuelewa dataset mpya — univariate, bivariate, na multivariate analysis. Correlation matrix na insights.', 1800,
            [['video_youtube', 'Exploratory Data Analysis kwa Python', 'https://www.youtube.com/watch?v=-o3AxdVcUtQ']],
            '<h2>Exploratory Data Analysis (EDA) — Kuelewa Dataset Mpya</h2><p>EDA ni hatua ya kwanza kabla ya kufanya analysis yoyote au kujenga model. Unachunguza dataset kwa njia nyingi ili kugundua patterns, anomalies, na insights.</p><h3>Framework ya EDA</h3><ol><li><strong>Understand Structure:</strong> df.info(), df.shape, df.dtypes, df.head()</li><li><strong>Summary Statistics:</strong> df.describe(), value_counts(), nunique()</li><li><strong>Missing Data Analysis:</strong> isnull().sum(), visualize kwa heatmap</li><li><strong>Univariate Analysis:</strong> Distribution ya kila variable moja moja</li><li><strong>Bivariate Analysis:</strong> Uhusiano kati ya variables mbili mbili</li><li><strong>Multivariate Analysis:</strong> Uhusiano kati ya variables nyingi — correlation matrix, pairplot</li></ol><h3>Mfano wa EDA Process</h3><pre><code># 1. Muundo\nprint(df.info())\nprint(f"Size: {df.shape}")\n\n# 2. Statistics\nprint(df.describe())\nprint("\\nNull values:")\nprint(df.isnull().sum())\n\n# 3. Categorical Analysis\nfor col in df.select_dtypes("object").columns:\n    print(f"\\n{col}: {df[col].value_counts()}")\n\n# 4. Numerical Analysis\nfor col in df.select_dtypes("number").columns:\n    print(f"\\n{col}: mean={df[col].mean():.2f}, std={df[col].std():.2f}")\n\n# 5. Outlier Detection\nfor col in df.select_dtypes("number").columns:\n    Q1, Q3 = df[col].quantile([0.25, 0.75])\n    IQR = Q3 - Q1\n    outliers = ((df[col] < Q1 - 1.5*IQR) | (df[col] > Q3 + 1.5*IQR)).sum()\n    print(f"{col}: outliers={outliers}")</code></pre><blockquote><strong>Jinsi ya Kuandika EDA:</strong> EDA nzuri inaishia na "Key Findings" — orodha ya mambo muhimu uliyogundua. Hizi ndizo zinaongoza analysis yako yote inayofuata. Bila EDA, unachambua data "kwa macho ya vipofu".</blockquote>');
